(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-async-rollout-weight-sync"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-1\">一 · 一次权重广播把整条流水线卡死的事故</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-2\">二 · 异步化换来的是什么，代价又落在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-3\">三 · 版本号是这条流水线的唯一真相</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-4\">四 · 适用边界的判断标准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-5\">五 · 权重槽切换被传输阻塞之后：这个方案治什么、不治什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-6\">六 · 权重落槽：从训练步到备用槽的写入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-7\">七 · 原子切换：双缓冲的指针翻转与在飞请求的透明性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-8\">八 · 采样与版本戳：样本携带生成时的权重身份</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-9\">九 · 回传与 staleness 计算：版本号到信任域半径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-10\">十 · 降权、丢弃与旧槽回收：闭环的最后一跳</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-11\">十一 · 步骤代价的横向对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-12\">十二 · 权重槽切换与在飞请求的边界条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-13\">十三 · 比率项的逐项解剖：$\\rho_t$ 到底在比什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-14\">十四 · staleness 的定义与 $\\epsilon_s$ 的构造</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-15\">十五 · 双缓冲槽切换的原子性与在飞请求的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-16\">十六 · 训练侧消费样本的伪代码与代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-17\">十七 · 一个具体例子：版本号错位如何让校正失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-18\">十八 · 失效边界：staleness 阈值、带宽墙与版本一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-19\">十九 · 请求形态：只有&quot;持续不断&quot;才配得上双缓冲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-20\">二十 · 长度分布：长尾决定权重切换的&quot;在飞半径&quot;</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-21\">二十一 · 并发与批大小：调度权在 rollout 引擎，但配方要匹配 staleness 预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-22\">二十二 · SLO 的错位：端到端 RL 吞吐不等于单请求延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-23\">二十三 · 负载不对时的三种塌陷形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-24\">二十四 · 配方的工程落点：把假设变成可观测的门槛</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-25\">二十五 · 负载配方：什么样的采样流才喂得饱双缓冲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-26\">二十六 · 硬件档位：按权重同步路径反推机型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-27\">二十七 · 并行拓扑：训练组与 rollout 组的切分方式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-28\">二十八 · 量化方案：权重槽里的数值格式与 staleness 的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-29\">二十九 · KV 策略：切换期间不清空的前提条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-30\">三十 · 调度参数：$k$ 步间隔、staleness 阈值与批在飞的联合定标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-31\">三十一 · 部署配方的失效边界：staleness 预算、带宽墙与版本一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-32\">三十二 · 双缓冲切换的带宽账：全量与差量两条路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-33\">三十三 · 显存的三份占用：权重槽、KV、在飞样本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-34\">三十四 · 通信拓扑：版本号也是一条消息</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-35\">三十五 · 功耗与热：重叠不等于免费</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-36\">三十六 · 尾延迟：staleness 分布的长尾才是真问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-37\">三十七 · 规模上去以后哪里先崩：一条排序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-38\">三十八 · 当权重推送本身成为瓶颈：带宽、显存与尾延迟的连锁失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-39\">三十九 · 精度漂移：staleness 与比率的可观测偏差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-40\">四十 · 权重槽切换的 OOM 与传输阻塞</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-41\">四十一 · 批抖动与路由不均</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-42\">四十二 · 尾延迟尖刺与在飞请求堆积</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-43\">四十三 · 监控面与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-44\">四十四 · 双缓冲权重槽的失效边界：从版本号错位到尾延迟尖刺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-45\">四十五 · 选型的第一性问题：等待从哪来、偏差从哪来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-46\">四十六 · 同族算法的分工边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-47\">四十七 · 决策表：按约束选主算法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-48\">四十八 · 适用条件的量化刻画</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-49\">四十九 · 组合与迁移的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-async-rollout-weight-sync-sec-50\">五十 · 异步权重同步的失效边界：同族调度方案怎么选</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:593px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 592.6 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"510.6\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">训练引擎完成一步更新后，将权重差量或全量写入rollout引擎的备用权重槽…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"510.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">rollout引擎在权重切换间隙继续用当前权重槽采样，采样请求不中断，KV…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"510.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">采样完成的样本携带其生成时的权重版本号回传训练侧，训练侧按版本号计算sta…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"510.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">训练侧对staleness超过阈值的样本降权或丢弃，并用信任域约束旧策略比率</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"510.6\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">权重槽切换后rollout引擎新请求使用新权重，旧权重槽在无在飞请求后回收</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-async-rollout-weight-sync-sec-1\">一 · 一次权重广播把整条流水线卡死的事故</h3>\n<p>某条线上 RL 流水线在扩容到多机后出现了一个很难归因的现象：训练侧的 step 时间没有变长，rollout 侧的采样吞吐却在每个训练 step 结束后出现一段规则的空窗，GPU 利用率曲线呈锯齿状。根因不在算子，而在同步语义。同步 RL 的循环是刚性的：rollout 引擎必须等训练 step 完成、梯度更新落地、权重广播完毕，才能开始下一轮采样。权重广播本身要经 NVLink 或 RDMA 把整份参数推到 rollout 侧，千亿参数规模下这是一次实打实的带宽事件；在这段时间里，rollout 引擎的 SM 无事可做，KV cache 与块表虽然还在显存里，但没有任何在飞请求去填它。事故的代价不是某一次广播慢，而是这种串行结构把“训练算”和“采样算”钉死成互斥的两段，端到端 RL 吞吐被权重同步的等待时间直接切掉一块。更糟的是，运维为了掩盖空窗把 batch 调大，结果 rollout 侧显存被 KV 撑爆，反而触发重调度，空窗更长。</p>\n<p>这个事故说明本算法要解决的具体问题只有一个：<strong>rollout 与训练的串行等待</strong>。它不解决 logprob 不可复现（那是批不变内核的题目），不解决量化误差累积（那是 NVFP4 稳定化的题目），也不解决前缀 KV 复用或预填解码配比。它站在调度与权重同步这一层，把两个进程组的时序解耦。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-2\">二 · 异步化换来的是什么，代价又落在哪里</h3>\n<p>把 rollout 引擎与训练引擎拆成两个进程组之后，训练侧每 k 步把权重增量或全量写入 rollout 引擎的备用权重槽，双缓冲切换原子完成；rollout 引擎在切换间隙继续用当前权重槽采样，请求不中断，KV 与块表保持。收益是直接的：权重同步的等待时间被采样填充，端到端 RL 吞吐提升，且切换对在飞请求透明——不会因为一次同步而清空 KV、丢弃批次。这就是本算法与“分页 KV 批量 Rollout”“异步 Rollout 流水线”等相邻条目分工不同的地方：那些条目管的是批内结构与流水级数，这里管的是权重版本的时间线。</p>\n<p>代价立刻以 staleness 的形式出现。rollout 用旧权重 $\\theta_{\\mathrm{old}}$ 采出的样本，回传时训练侧的策略已经是 $\\theta_{\\mathrm{new}}$，off-policy 比率不再等于 1：</p>\n<div class=\"formula\">$$\\rho_t=\\frac{\\pi_{\\theta_{\\mathrm{new}}}(a_t\\mid s_t)}{\\pi_{\\theta_{\\mathrm{old}}}(a_t\\mid s_t)},\\quad w_t=\\min\\big(\\rho_t,\\ \\mathrm{clip}(\\rho_t,1-\\epsilon_s,1+\\epsilon_s)\\big)$$</div>\n<p>其中 $\\epsilon_s$ 随 staleness 动态收紧。若阈值不当，比率偏离 1 的样本会把策略梯度拉偏，直至训练发散。这不是理论洁癖：在线上表现为 reward 曲线先升后崩，且崩点与扩容后权重广播变慢的时间点吻合。超参敏感、调参成本高，是这条路线绕不开的账。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-3\">三 · 版本号是这条流水线的唯一真相</h3>\n<p>机制的关键不在双缓冲本身，而在样本携带权重版本号回传。采样完成的样本带上其生成时的权重版本号，训练侧按版本号计算 staleness，对超过阈值的样本降权或丢弃，并用信任域约束旧策略比率。伪代码思路是：训练侧维护一个版本计数器，每次权重写入备用槽即递增；rollout 侧每个请求在发起时锁定当前槽的版本号，随样本一起回传；训练侧收到样本后做 $s = v_{\\text{train}} - v_{\\text{sample}}$，再令 $\\epsilon_s = f(s)$ 收紧裁剪区间。权重槽切换后新请求走新权重，旧权重槽在无在飞请求后回收——回收条件是“无在飞”，不是“切换完成”，否则正在生成的序列会被中途换权重，样本内部策略不一致，版本号也失去意义。</p>\n<p>系统代价在这里体现为显存与带宽的双份占用：双缓冲意味着两份权重常驻，千亿参数下这是可观的显存开销，挤占 KV 空间；全量同步在千亿参数上传输量大，若带宽不足，双缓冲切换被传输阻塞，rollout 与训练的重叠收益被抵消——事故里的锯齿会重新出现，只是换了个位置。差量同步省带宽，但需维护版本与合并逻辑，故障恢复复杂；版本号与权重槽不一致时 staleness 计算错误，信任域校正直接失效，这是比带宽更隐蔽的失败模式。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-4\">四 · 适用边界的判断标准</h3>\n<p>适用与否不看模型大小，看三个条件是否同时成立。其一，rollout 与训练确实解耦为两个进程组，且采样请求是持续不断的流，批大小由 rollout 引擎调度决定，SLO 以端到端 RL 吞吐与权重切换对在飞请求透明为主——材料未给出具体批大小与 SLO 数值，工程上应以“切换期间请求不中断”为验收口径。其二，权重同步路径有足够的 NVLink 或 RDMA 带宽支撑双缓冲切换不被传输阻塞，硬件档位与并行拓扑需按实际集群核算，材料未给出具体数值。其三，任务能容忍一定程度的 off-policy：staleness 阈值需按模型与任务调参，阈值过紧则丢弃样本过多、吞吐收益归零，过松则梯度有偏。</p>\n<p>不适用的情况同样清晰。若模型规模使全量同步的传输时间接近甚至超过一个训练 step，双缓冲的重叠窗口被吃光，异步化只剩复杂度没有收益；若故障恢复要求强一致、版本号必须与权重槽严格对齐而团队没有相应的版本管理能力，差量同步的合并逻辑会成为新的故障源；若任务对策略新鲜度极度敏感、几乎不允许旧样本进入梯度，那么应回到同步语义，或改用其他条目讨论的流水线级重叠而非权重级异步。</p>\n<table class=\"mini\"><thead><tr><th>判断维度</th><th>适合异步权重同步</th><th>不适合</th></tr></thead><tbody><tr><td>时序结构</td><td>rollout 与训练双进程组，采样流持续</td><td>单进程串行，无重叠窗口</td></tr><tr><td>带宽</td><td>NVLink/RDMA 足以让切换不阻塞采样</td><td>全量同步时间逼近一个 step</td></tr><tr><td>样本容忍度</td><td>可按版本号降权/丢弃，信任域可收紧</td><td>几乎不允许旧样本进梯度</td></tr><tr><td>运维能力</td><td>能维护版本号与权重槽一致性</td><td>无版本管理，故障恢复要求强一致</td></tr></tbody></table>\n<p>把这张表落到事故复盘上：那次扩容之所以失败，是因为带宽条件与版本管理两条同时不满足，却先上了异步。正确的顺序是先量权重广播的实际耗时，确认双缓冲切换能藏在采样窗口内，再引入版本号与 staleness 阈值；否则异步化只是把串行等待换成了有偏梯度与更复杂的故障恢复。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-5\">五 · 权重槽切换被传输阻塞之后：这个方案治什么、不治什么</h3>\n<p>先把事故形态摆出来。一条千亿参数模型的异步 RL 流水线，rollout 引擎与训练引擎已经拆成两个进程组，双缓冲权重槽也接好了。训练侧每 k 步把权重全量经 NVLink/RDMA 推送到 rollout 引擎的备用槽，切换原子完成。问题出在带宽争抢上：当训练侧同时在做梯度 AllReduce、rollout 侧同时在拉长序列的 KV 块时，权重传输被挤到队列尾部，备用槽迟迟填不满。于是双缓冲退化成单缓冲——rollout 引擎在切换间隙只能继续用当前槽采样，采样请求确实没中断、KV 与块表也确实保住了，但权重版本号在样本上越积越旧。训练侧按版本号算出的 staleness 迅速越过阈值，大批样本被降权或丢弃，有效批被抽空；信任域按 staleness 收紧后 $\\epsilon_s$ 逼近零，旧样本的更新幅度被压到几乎不产生梯度。表面上 rollout 与训练在重叠执行，端到端 RL 吞吐反而低于同步基线——重叠收益被传输阻塞和样本丢弃两头吃掉。这个事故说明该方案的收益不是无条件的：它把“等权重”的串行等待换成了“权重传输与采样争带宽”的并发竞争，前者是确定性延迟，后者是不确定性抖动。</p>\n<p>它解决的具体问题只有一个：同步 RL 中 rollout 必须等训练 step 完成与权重广播后才能开始下一轮，rollout 与训练串行导致 GPU 在等待权重时闲置。异步化把这段等待用采样填满，代价是旧权重采样引入 staleness，使策略梯度有偏。校正手段是带版本号的信任域约束：样本回传时携带生成时的权重版本号，训练侧据此计算 staleness，对超阈值样本降权或丢弃，并用随 staleness 收紧的比率裁剪约束旧策略更新，即</p>\n<div class=\"formula\">$$\\rho_t=\\frac{\\pi_{\\theta_{\\mathrm{new}}}(a_t\\mid s_t)}{\\pi_{\\theta_{\\mathrm{old}}}(a_t\\mid s_t)},\\quad w_t=\\min\\big(\\rho_t,\\ \\mathrm{clip}(\\rho_t,1-\\epsilon_s,1+\\epsilon_s)\\big),\\quad \\epsilon_s=f(\\text{staleness})$$</div>\n<p>其中 $\\theta_{\\mathrm{old}}$ 是样本生成时的权重版本。注意这个式子的性质：它不是在修正数据，而是在缩小可用数据的更新幅度——staleness 越大，$\\epsilon_s$ 越紧，样本对梯度的贡献越小。所以该方案的稳定性上限由“有效样本量”决定，而不是由双缓冲的工程精巧度决定。</p>\n<p>边界因此可以划得很清楚。它不解决 logprob 不可复现的问题（那是批不变内核的职责），也不解决量化误差（NVFP4 稳定性的职责），更不解决并行拓扑与通信库本身的效率——它只作用在调度与权重同步这一层。失效条件有三类。其一是带宽不足：千亿参数模型上权重全量同步传输量大，若 NVLink/RDMA 带宽被训练集合通信或 KV 传输占满，双缓冲切换被传输阻塞，rollout 与训练的重叠收益被抵消，这正是上面事故的机理。其二是版本一致性：差量同步需维护版本与合并逻辑，故障恢复复杂，一旦版本号与权重槽不一致，样本 staleness 计算错误，信任域校正整体失效，且这种错误不会报错、只会表现为训练缓慢发散。其三是超参敏感：staleness 阈值与 $\\epsilon_s$ 的映射函数需按模型与任务调参，阈值过松则 off-policy 比率偏离 1 导致发散，过紧则有效批坍缩、吞吐回落。三类失效的共同点是它们都不体现在单步延迟上，而体现在端到端 RL 吞吐与收敛曲线上，监控必须挂在“有效样本率”和“staleness 分布”两个指标上，而不是只看权重切换是否成功。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>方案表现</th><th>系统代价落点</th></tr></thead><tbody><tr><td>权重传输带宽充裕、k 步间隔合理</td><td>切换对在飞请求透明，采样不中断</td><td>显存：双份权重槽常驻，KV 与块表不清空</td></tr><tr><td>带宽被训练通信挤占</td><td>备用槽填充延迟，staleness 累积</td><td>吞吐：有效批被丢弃抽空，重叠收益归零</td></tr><tr><td>版本号与槽不一致</td><td>staleness 计算错误，校正失效</td><td>稳定性：缓慢发散，无显式报错</td></tr></tbody></table>\n<p>工程判断上，这个方案适用于 rollout 与训练已解耦、且权重传输有独立带宽保障的异步 RL 流水线；不适合权重规模超出可用传输预算、或对收敛可复现性要求高于吞吐的场景。部署时把权重推送放在与训练集合通信不同的通道上，把 staleness 阈值当作一等超参随模型规模一起标定，并在双缓冲之外保留“传输未完成则拒绝切换”的显式门控——宁可短暂退化为同步，也不要让版本号在无感知的情况下漂移。</p>\n<h3 id=\"alg-async-rollout-weight-sync-sec-6\">六 · 权重落槽：从训练步到备用槽的写入</h3>\n<p>异步流水线的第一个动作发生在训练侧一步优化器更新完成之后。此时训练引擎持有新的参数张量，但它并不直接改写 rollout 正在使用的权重，而是把差量或全量写入 rollout 引擎的<strong>备用权重槽</strong>。这一步的输入是训练引擎刚算出的参数增量（或完整参数分片），输出是备用槽中一份可被原子切换的、版本号已递增的权重副本。写入路径走 NVLink 或 RDMA：同一 NVL72 域内走 NVLink，跨节点走 RDMA，具体拓扑与并行切分方式材料未给出数值，工程上按训练侧的 TP/EP 切分与 rollout 侧的切分做重映射，重映射本身是这一步最容易被低估的开销。</p>\n<p>代价分三块。其一是<strong>传输量</strong>：全量同步在千亿参数模型上意味着每次切换都要搬动整个参数集，即使按 BF16 计也是数百 GB 量级，带宽不足时写入会阻塞切换，双缓冲的重叠收益被直接抵消；差量同步把传输量压到增量大小，但要求两侧维护一致的版本链与合并逻辑。其二是<strong>写入期间的算力占用</strong>：拷贝引擎与计算流争用同一条链路，rollout 侧的采样若同时在进行，KV 读取的带宽会被挤压。其三是<strong>故障面</strong>：版本号与权重槽不一致时，后续所有样本的 staleness 计算都会错位，信任域校正随之失效，这是差量方案最典型的失败模式。工程判断上，差量同步适合参数更新稀疏或低秩的场景，全量同步适合切换频率低、带宽充裕的场景，两者不能靠“大概”混用。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-7\">七 · 原子切换：双缓冲的指针翻转与在飞请求的透明性</h3>\n<p>写入完成后，切换本身是一次<strong>原子指针翻转</strong>：rollout 引擎把“当前权重槽”的引用从 A 槽改为 B 槽，版本号随之生效。这一步的输入是两个已就绪的槽与一个待生效的版本号，输出是一个新的当前槽引用，代价接近于零——真正的代价不在翻转，而在翻转的<strong>可见性边界</strong>。翻转只对新到达的请求生效；已经在飞的请求继续持有它们进入时抓取的权重槽引用，直到这批请求全部完成采样。</p>\n<p>这就是双缓冲对在飞请求透明的机制：rollout 引擎在切换间隙继续用当前槽采样，采样请求不中断，KV 与块表保持不清空。若没有这层透明性，同步点会强制清空批次与 KV，把已经付出的预填成本扔掉，端到端吞吐反而下降。用伪代码表达调度侧的判定：</p>\n<div class=\"formula\">$$\\text{retire}(A)\\ \\text{iff}\\ \\text{inflight}(A)=0\\ \\wedge\\ \\text{cur}=B$$</div>\n<p>即旧槽 A 只有在无在飞请求且已不是当前槽时才可回收。这里的工程代价是<strong>显存占用翻倍</strong>：两个权重槽同时驻留，对显存紧张的部署是硬约束，尤其在权重与 KV 共享同一池的情况下，双缓冲会把可用 KV 块数压低，间接影响批大小与延迟。另一个代价是<strong>回收时机的判定成本</strong>：在飞请求计数必须精确，计数泄漏会让旧槽永不回收，形成显存慢性泄漏；计数过早归零则会让仍在使用旧槽的请求读到被覆写的权重，产生静默的数值错误而非崩溃，这类错误最难定位。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-8\">八 · 采样与版本戳：样本携带生成时的权重身份</h3>\n<p>采样阶段本身与常规 rollout 无异，本算法的特殊之处在于每个输出 token 序列必须携带<strong>生成时的权重版本号</strong>。输入是提示、当前槽引用与调度器分配的批，输出是 token 序列加上一个版本戳，代价是每个样本多一个整型字段的元数据，以及版本号必须与槽引用严格绑定——绑定错位就是前面说的 staleness 计算错误。版本戳应在请求进入解码循环时抓取一次，而不是每个 token 抓一次，否则同一序列内部会出现跨版本的 logprob，破坏重要性比率的自洽性。</p>\n<p>这一步的系统代价主要在<strong>批调度</strong>：切换发生后，同一个连续批里可能同时存在旧版本与新版本的请求，调度器不能假设批内权重一致。若为了简化而按版本分桶，会造成批的碎片化，降低 GPU 利用率；若不分桶，则要求内核在计算 logprob 时按请求读取对应槽，权重访问的局部性变差，L2 命中率下降。工程上通常选择让切换点与批边界对齐来规避这一冲突，代价是切换要等待当前批结束，重叠窗口被压缩——这是透明性与吞吐之间必须显式做出的取舍，而不是可以含糊过去的细节。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-9\">九 · 回传与 staleness 计算：版本号到信任域半径</h3>\n<p>样本回传训练侧后，训练侧按版本号计算 staleness：当前训练步的权重版本减去样本生成时的版本，得到该样本落后了多少步。输入是样本的版本戳与训练侧当前版本，输出是每个样本的 staleness 标量，代价是训练侧的<strong>版本账本</strong>必须与 rollout 侧一致，任何一侧的版本推进逻辑分叉都会让 staleness 失真。随后信任域半径按 staleness 收紧：</p>\n<div class=\"formula\">$$\\rho_t=\\frac{\\pi_{\\theta_{\\mathrm{new}}}(a_t\\mid s_t)}{\\pi_{\\theta_{\\mathrm{old}}}(a_t\\mid s_t)},\\quad w_t=\\min\\big(\\rho_t,\\ \\mathrm{clip}(\\rho_t,1-\\epsilon_s,1+\\epsilon_s)\\big),\\quad \\epsilon_s=f(\\text{staleness})$$</div>\n<p>其中 $\\theta_{\\mathrm{old}}$ 是样本生成时的权重版本，$\\epsilon_s$ 随 staleness 单调收紧。这一步的代价是<strong>计算与显存</strong>：为每个样本重算旧策略 logprob 需要一次前向，若旧权重槽已被回收，就必须在回传时一并带上 logprob 或保留旧槽更久，二者都增加显存或带宽开销。更实际的代价是<strong>超参敏感</strong>：$f$ 的形状决定收紧速度，收得太慢则 off-policy 比率偏离 1，策略梯度有偏、训练发散；收得太快则大量样本被裁掉，有效批量骤减，吞吐收益被抵消。材料明确指出阈值需按模型与任务调参，这意味着调参成本是这套机制的结构性代价，而非一次性投入。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-10\">十 · 降权、丢弃与旧槽回收：闭环的最后一跳</h3>\n<p>拿到 staleness 与重要性比率后，训练侧执行两级处理：对 staleness 超过阈值的样本<strong>降权或直接丢弃</strong>，对保留样本用 $\\epsilon_s$ 收紧后的 clip 约束更新幅度。输入是带版本戳的样本与当前策略，输出是进入梯度计算的加权样本集，代价体现在<strong>有效批量</strong>上——丢弃比例越高，单位训练步的样本利用率越低，端到端吞吐的提升被部分回吐。降权比丢弃温和，但会引入方差，二者之间的选择取决于任务对梯度噪声的容忍度。</p>\n<p>闭环的最后一跳是旧槽回收：当某版本的在飞请求计数归零且该槽不再是当前槽时，回收其显存。这一步的代价是<strong>回收延迟与显存峰值</strong>：为了给回传的 logprob 重算留出窗口，旧槽往往要保留比“无在飞请求”更久，双缓冲实际上退化为三槽甚至更多，显存压力进一步上升。工程判断上，若模型规模使权重槽本身就很昂贵，应优先让样本在生成时携带 logprob 而非保留旧槽，用带宽换显存；若回传带宽紧张，则反向选择。这一取舍与千亿参数模型上全量同步的传输量直接耦合，是部署配方里必须显式写清的一条。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-11\">十一 · 步骤代价的横向对照</h3>\n<p>把五步的代价放在一张表里，可以看出瓶颈并不均匀分布：写入与回收吃带宽和显存，切换吃调度精度，回传吃算力与超参。任何一步的代价失控都会让重叠收益归零，因此工程上应按最贵的一步来定容量，而不是按平均值。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody>\n<tr><td>权重落槽</td><td>训练侧参数增量/全量</td><td>备用槽权重副本+新版本号</td><td>传输量、链路争用、版本一致性</td></tr>\n<tr><td>原子切换</td><td>两槽就绪+待生效版本</td><td>当前槽引用翻转</td><td>双槽显存、在飞计数精度</td></tr>\n<tr><td>采样与版本戳</td><td>提示+槽引用+批</td><td>token 序列+版本戳</td><td>批碎片化、权重访问局部性</td></tr>\n<tr><td>回传与 staleness</td><td>版本戳+当前版本</td><td>staleness 标量+$\\epsilon_s$</td><td>旧 logprob 重算、超参调优</td></tr>\n<tr><td>降权/丢弃与回收</td><td>加权样本集+在飞计数</td><td>梯度输入+释放的槽</td><td>有效批量损失、回收延迟</td></tr>\n</tbody></table>\n<p>对照的结论落在具体机制上：切换的透明性由在飞计数保证，而计数的精确性又依赖版本号与槽引用的严格绑定；一旦绑定松动，staleness 失真会让 $\\epsilon_s$ 的收紧失去意义，clip 退化为固定半径，异步化的全部收益建立在错误的校正之上。因此这套流水线的正确性锚点不在采样侧，而在<strong>版本账本</strong>——它是唯一贯穿五个步骤、且任何一处错位都无法在后续步骤中被检测出来的状态。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-12\">十二 · 权重槽切换与在飞请求的边界条件</h3>\n<p>双缓冲权重槽的原子切换只在“备用槽已完整就绪”时成立，因此真正的边界不在切换指令本身，而在传输完成与在飞请求排空这两条时间线能否对齐。设单次权重推送耗时为 <span class=\"formula\">$$T_{\\text{push}}=\\frac{B_w}{BW_{\\text{link}}}+T_{\\text{merge}}$$</span>，其中 $B_w$ 为全量或差量字节数，$BW_{\\text{link}}$ 为 NVLink 或 RDMA 的有效带宽，$T_{\\text{merge}}$ 为差量合并与版本校验开销。当 $T_{\\text{push}}$ 超过一个训练步的采样填充时间，rollout 侧会在当前槽上采样到“无新权重可切”的状态，重叠收益被传输阻塞吞掉——这是千亿参数全量同步最典型的失效条件。工程判断是：全量同步只在 $B_w/BW_{\\text{link}}$ 远小于单步训练时间时可用，否则必须走差量，而差量又把复杂度转移到版本合并逻辑上。</p>\n<p>在飞请求的回收条件是第二个边界。旧权重槽必须等到“以该版本号生成的所有请求均已回传或超时”才能释放，否则样本携带的版本号会指向已被覆写的槽，staleness 计算直接失真。设某槽的在飞请求集合为 $S_v$，回收判据为 $|S_v|=0 \\lor \\text{age}(S_v)&gt;\\tau_{\\text{drain}}$；$\\tau_{\\text{drain}}$ 过长则双缓冲退化为单缓冲，切换被迫等待，$\\tau_{\\text{drain}}$ 过短则产生版本号与权重槽不一致，信任域校正失效。长序列解码请求是这里的钉子户：一个在飞请求可能跨越多次权重切换，其 KV 与块表虽保持，但样本的 $\\theta_{\\text{old}}$ 已落后多个版本。</p>\n<p>校正侧的代价体现在超参敏感度上。按版本号计算的 staleness 进入信任域后，比率与权重为 <span class=\"formula\">$$\\rho_t=\\frac{\\pi_{\\theta_{\\mathrm{new}}}(a_t\\mid s_t)}{\\pi_{\\theta_{\\mathrm{old}}}(a_t\\mid s_t)},\\quad w_t=\\min\\big(\\rho_t,\\ \\mathrm{clip}(\\rho_t,1-\\epsilon_s,1+\\epsilon_s)\\big)$$</span>，$\\epsilon_s$ 随 staleness 收紧。收紧过快会把大量旧样本压成零梯度，rollout 算力白费、有效批缩小；收紧过慢则 off-policy 比率偏离 1，策略梯度有偏直至发散。阈值需按模型与任务调参，这本身就是持续的调参成本，且与批调度耦合：批越大，批内样本的版本号跨度越大，单一 $\\epsilon_s$ 越难覆盖。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>触发信号</th><th>系统代价</th></tr></thead><tbody><tr><td>推送慢于采样填充</td><td>备用槽长期未就绪</td><td>重叠收益归零，rollout 空转</td></tr><tr><td>在飞请求跨多版本</td><td>版本号与槽不一致</td><td>staleness 误算，校正失效</td></tr><tr><td>$\\epsilon_s$ 过紧</td><td>有效样本骤减</td><td>吞吐下降，算力浪费</td></tr><tr><td>差量合并出错</td><td>故障恢复后版本漂移</td><td>需全量重推，恢复窗口拉长</td></tr></tbody></table>\n<p>因此该方案的适用边界应表述为：rollout 与训练解耦、且权重传输时间可被采样填充吸收的流水线；一旦模型规模把 $T_{\\text{push}}$ 推到与训练步同量级，或请求形态以长序列为主导致在飞集合难以排空，双缓冲的透明性就不再成立，需退回更短同步周期或引入分层权重槽。</p>\n<h3 id=\"alg-async-rollout-weight-sync-sec-13\">十三 · 比率项的逐项解剖：$\\rho_t$ 到底在比什么</h3>\n<p>把 $\\mathcal{L}_{\\text{async}}$ 拆开看，第一层是重要性比率 $\\rho_t=\\pi_{\\theta_{\\mathrm{new}}}(a_t\\mid s_t)/\\pi_{\\theta_{\\mathrm{old}}}(a_t\\mid s_t)$。分子是训练侧当前权重对已采动作的重新打分，分母是样本生成时那一版权重的打分——注意分母不是\"上一训练步\"的权重，而是样本自己携带的版本号所指的那一槽权重。这一点决定了实现上必须做两件事：其一，rollout 引擎在样本出队时把版本号写进样本元数据，而不是在回传时按\"当前最新版本\"猜测；其二，训练侧必须能对任意历史版本重算 logprob，或者由 rollout 侧在生成时就把 $\\log\\pi_{\\theta_{\\mathrm{old}}}$ 落盘随样本带回。后者更省，因为重算需要把旧权重槽保留到该版本所有样本消费完毕，显存代价随版本窗口线性增长；前者省显存但把计算压到训练侧，且要求旧权重可寻址。</p>\n<p>推导的关键一步在于：把\"旧样本用于新策略\"这件事写成对旧策略期望的修正。设样本由 $\\theta_{\\mathrm{old}}$ 采出，我们要估计的是 $\\theta_{\\mathrm{new}}$ 下的期望，标准的重要性采样恒等式给出</p>\n<div class=\"formula\">$$\\mathbb{E}_{(s,a)\\sim\\pi_{\\theta_{\\mathrm{new}}}}[A]=\\mathbb{E}_{(s,a)\\sim\\pi_{\\theta_{\\mathrm{old}}}}\\left[\\frac{\\pi_{\\theta_{\\mathrm{new}}}(a\\mid s)}{\\pi_{\\theta_{\\mathrm{old}}}(a\\mid s)}A\\right]$$</div>\n<p>这一步不含任何近似，偏差全部来自比率估计的方差与 clip 引入的收缩。clip 的作用不是\"修正偏差\"，而是用有偏换低方差：当 $\\rho_t$ 因 staleness 被推到 $1\\pm\\epsilon_s$ 之外时，梯度不再随比率线性放大，避免单个陈旧样本主导更新。因此 $\\epsilon_s=f(\\text{staleness})$ 的单调性方向必须是\"staleness 越大、区间越窄\"，即旧样本被允许的更新幅度更小——这与 PPO 固定 $\\epsilon$ 的直觉相反，是异步场景特有的收紧。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-14\">十四 · staleness 的定义与 $\\epsilon_s$ 的构造</h3>\n<p>staleness 的可实现定义有三种粒度，选哪种直接决定伪代码形态。版本差 $\\Delta v=v_{\\mathrm{train}}-v_{\\mathrm{sample}}$ 最粗，只数权重槽切换了几次；步差 $\\Delta s$ 数训练侧在样本生成后完成了多少 optimizer step，更贴近策略漂移；token 级加权则按样本内每个 token 生成时刻的版本号做平均，最细但元数据开销大。工程上取 $\\Delta s$ 为主、$\\Delta v$ 做上界截断，因为 $\\Delta v$ 可以直接由双缓冲槽的切换计数原子读取，不需要逐样本追踪。</p>\n<p>$\\epsilon_s$ 的构造要满足两个约束：$\\epsilon_s(\\Delta s=0)=\\epsilon_0$ 退化为常规信任域；$\\epsilon_s$ 随 $\\Delta s$ 单调不增且在阈值 $\\Delta s_{\\max}$ 处趋于零或触发丢弃。一个可落地的形式是</p>\n<div class=\"formula\">$$\\epsilon_s=\\epsilon_0\\cdot\\exp\\!\\left(-\\frac{\\Delta s}{\\tau}\\right),\\qquad \\text{drop if }\\Delta s&gt;\\Delta s_{\\max}$$</div>\n<p>$\\tau$ 是衰减尺度，量纲为训练步。它的物理含义是\"策略在多少步内漂移到不可信\"，与学习率、批大小、任务非平稳性都相关，因此不能全局写死，应按模型与任务调参——这正是该算法超参敏感的来源。指数形式的好处是无需分段即可平滑收紧，坏处是 $\\tau$ 与 $\\epsilon_0$ 耦合，调一个牵动另一个；若改用线性 $\\epsilon_s=\\epsilon_0(1-\\Delta s/\\Delta s_{\\max})$，两个参数解耦、调参成本低，但在 $\\Delta s$ 接近上限时收缩过猛，容易把有效样本全部 clip 掉、有效批骤减。选择哪种取决于 rollout 与训练的速率比：速率比大（rollout 远快于训练）时 staleness 分布尾巴长，指数形式更稳。</p>\n<p>系统代价在这里显形：$\\Delta s_{\\max}$ 越小，丢弃率越高，rollout 引擎产出的样本被训练侧浪费，端到端吞吐的实际收益被抵消；$\\Delta s_{\\max}$ 越大，clip 区间越窄导致梯度信号弱，收敛变慢。二者共同决定\"重叠收益\"能否兑现，而不是单看权重传输带宽。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-15\">十五 · 双缓冲槽切换的原子性与在飞请求的边界</h3>\n<p>权重槽切换的语义必须精确到\"哪些请求算在飞\"。定义在飞请求为：已进入调度队列、已分配 KV 块、尚未把最后一个 token 写回结果队列的请求。切换时刻 $T$ 之前出队的请求继续用旧槽，之后出队的用新槽；但一个请求可能在 $T$ 之前出队、在 $T$ 之后还在解码，此时它的后续 token 由旧权重生成，版本号必须仍是旧版本，不能因为槽已切换就改写。实现上给每个请求在准入时绑定一个槽句柄（指向权重槽的引用计数），解码循环只读该句柄，不读\"当前槽指针\"。旧槽的回收条件是引用计数归零，即所有绑定它的请求都已结束或已被取消。</p>\n<p>伪代码落到可实现，核心是三个结构：槽数组（双缓冲，带版本号与引用计数）、请求到槽的绑定、以及切换时的原子指针交换。</p>\n<ul>\n<li>槽结构：<code>slot[i] = {version, refcount, weight_ptr}</code>，$i\\in\\{0,1\\}$，另有 <code>active_idx</code> 原子变量。</li>\n<li>准入：请求入队时读 <code>active_idx</code>，对该槽 <code>refcount++</code>，把 <code>version</code> 写入请求元数据。</li>\n<li>切换：训练侧写完备用槽后，<code>active_idx</code> 原子翻转；翻转前必须确认备用槽写入完成（用 fence 或完成事件），否则新请求可能读到半写权重。</li>\n<li>回收：请求结束时 <code>refcount--</code>；训练侧在准备下一次写入前检查目标槽 <code>refcount==0</code>，否则等待或延迟写入。</li>\n</ul>\n<p>这里有一个容易忽略的代价：如果备用槽迟迟不能回收（长请求、长解码），训练侧的写入会被阻塞，双缓冲退化为单缓冲，重叠收益消失。千亿参数模型上全量同步传输量大，若带宽不足，写入本身就会把切换窗口拉长，rollout 在这段时间只能继续用旧权重，staleness 被动增大——这是\"传输阻塞切换\"的失败模式，与 $\\epsilon_s$ 调参无关，是纯带宽问题。差量同步能缓解传输量，但引入版本合并逻辑：备用槽必须在旧槽基础上叠加差量，若合并失败或版本号错位，样本 staleness 计算就错，信任域校正随之失效。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-16\">十六 · 训练侧消费样本的伪代码与代价核算</h3>\n<p>训练侧的循环要按版本号分组消费，而不是按到达顺序混批。混批会让同一 micro-batch 内样本的 $\\Delta s$ 方差极大，$\\epsilon_s$ 只能取最严的值，等于对新鲜样本也过度 clip。按版本号分桶、桶内取 $\\Delta s$ 上界做 $\\epsilon_s$，可以在不牺牲新鲜样本的前提下约束陈旧样本。</p>\n<ul>\n<li>收样本：从回传队列取样本，读 <code>version</code>，算 $\\Delta s=v_{\\mathrm{train}}-\\text{version}$。</li>\n<li>过滤：$\\Delta s&gt;\\Delta s_{\\max}$ 直接丢弃并计数（丢弃率是容量规划的关键指标）。</li>\n<li>打分：用当前权重算 $\\log\\pi_{\\theta_{\\mathrm{new}}}$，与样本带回的 $\\log\\pi_{\\theta_{\\mathrm{old}}}$ 相减得 $\\log\\rho_t$，取 exp 得 $\\rho_t$。</li>\n<li>加权：$w_t=\\min(\\rho_t,\\mathrm{clip}(\\rho_t,1-\\epsilon_s,1+\\epsilon_s))$，乘 $\\hat A_t$ 进梯度。</li>\n<li>记账：按版本桶统计有效样本数、平均 $\\Delta s$、clip 命中率，供 $\\tau$ 与 $\\Delta s_{\\max}$ 调参。</li>\n</ul>\n<p>代价核算要盯三个量。显存：旧权重槽若需保留以重算 logprob，等于多一份权重常驻，对 B200 级别的单卡是实打实的占用；若改为样本带回 logprob，则显存省下但样本元数据变大，回传带宽上升。带宽：权重传输走 NVLink 或 RDMA，全量同步的字节数与参数量成正比，差量同步的字节数与更新稀疏度成正比，后者在优化器状态稠密时并不省。延迟：切换的原子性保证不引入请求级停顿，但训练侧的写入等待会转化为 staleness 的增长，最终以丢弃率与收敛速度的形式计入端到端吞吐。三者中任意一个成为瓶颈，重叠收益都会被吃掉，因此容量规划必须同时看权重传输时间、rollout 采样时间与训练 step 时间三者的比例，而不是只看 GPU 利用率。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-17\">十七 · 一个具体例子：版本号错位如何让校正失效</h3>\n<p>设训练侧完成第 $n$ 步更新，把差量写入备用槽并翻转 <code>active_idx</code>，槽版本号记为 $n$。此时 rollout 引擎仍有若干请求绑定在版本 $n-1$ 的槽上，它们继续解码，样本回传时携带 $n-1$。训练侧在第 $n+1$ 步消费这些样本，$\\Delta s=1$，$\\epsilon_s$ 按公式收紧，$\\rho_t$ 被 clip，逻辑自洽。问题出在差量合并：若备用槽的写入是\"在旧槽基础上叠加\"，而旧槽此时仍被在飞请求读取，叠加就会污染在飞请求后续 token 的权重——它们名义上还是版本 $n-1$，实际已混入 $n$ 的增量。此时样本带回的 $\\log\\pi_{\\theta_{\\mathrm{old}}}$ 与真实生成分布不符，$\\rho_t$ 的分母错了，clip 再准也无意义。规避方式是差量写入必须落到独立的备用缓冲区、合并完成后再整体切换指针，而不是原地叠加；代价是多一份缓冲区显存与一次拷贝带宽。</p>\n<p>另一个错位来源是版本号与槽的映射。若回收旧槽后复用其编号，而某样本的版本号仍指向该编号，训练侧会把新槽的权重误认为样本的生成权重，$\\Delta s$ 算成 0，$\\epsilon_s$ 取最宽，陈旧样本被当作新鲜样本全额使用——这是最危险的失效，因为它不报错、只让训练悄悄发散。防御手段是版本号单调递增、槽编号与版本号解耦、样本元数据里同时存版本号与槽句柄的世代号，消费时校验世代号一致才继续。</p>\n<p>把这两点合起来看，本算法的稳定性不取决于公式本身，而取决于版本追踪的完整性：$\\epsilon_s=f(\\text{staleness})$ 只有在 staleness 算对时才有意义。工程判断是——先保证版本号、槽世代、logprob 三者的一致性校验，再谈 $\\tau$ 与 $\\Delta s_{\\max}$ 的调参；校验缺失时，任何信任域收紧都只是给错误的比率乘一个错误的系数。</p>\n\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-18\">十八 · 失效边界：staleness 阈值、带宽墙与版本一致性</h3>\n<p>这套方案并非无条件加速。第一个边界是 staleness 阈值本身：$\\epsilon_s=f(\\text{staleness})$ 若取常数，旧样本的 $\\rho_t$ 会系统性偏离 1，clip 后梯度方向仍被污染；若随 staleness 线性收紧，则阈值过大时旧样本被大量丢弃，rollout 引擎产出的 token 变成无效算力，端到端吞吐反而下降。工程上应把 staleness 定义为“样本生成时权重版本与当前训练权重版本之差”，按版本号而非墙钟时间计算，避免慢节点上的样本被误判。第二个边界是带宽墙：千亿参数模型全量同步一次即数十 GB 级传输，若 NVLink/RDMA 有效带宽不足以在 k 步训练窗口内完成写入，备用权重槽迟迟不就绪，双缓冲退化为单缓冲，rollout 被迫在切换点停顿，重叠收益被抵消。此时应改用差量同步，但差量必须附带基版本号，合并逻辑要能处理乱序到达与槽位回滚。</p>\n<p>推导的关键一步在于把“版本差”映射为信任域半径：设样本版本为 $v$，当前版本为 $V$，staleness $s=V-v$，则 $\\epsilon_s=\\epsilon_0\\cdot g(s)$，$g$ 单调递减且 $g(0)=1$。代入目标函数得</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\text{async}} = \\mathbb{E}_{(s,a)\\sim\\pi_{\\theta_v}}\\left[\\min\\left(\\rho_t \\hat A_t,\\ \\text{clip}(\\rho_t, 1-\\epsilon_0 g(V-v), 1+\\epsilon_0 g(V-v))\\hat A_t\\right)\\right]$$</div>\n<p>可见 $g$ 的形状直接决定有效样本比例：$g$ 衰减过快，$s\\ge 2$ 的样本几乎全被裁掉；衰减过慢，$\\rho_t$ 的方差随 $s$ 增长而发散。伪代码落到可实现层面，训练侧维护 <code>slot[2]</code> 与 <code>ver[2]</code>，每 k 步写备用槽后原子交换 <code>active</code> 索引；rollout 侧每个请求在准入时快照 <code>active</code> 与 <code>ver[active]</code>，回传样本时携带该版本号；训练侧按 <code>s = cur_ver - sample_ver</code> 查表得 $\\epsilon_s$，超阈值样本置零权重而非直接删除，以保持 batch 形状稳定。代价体现在显存与调度两侧：双缓冲使权重常驻显存翻倍，在 KV cache 已占大头的解码场景中需预留槽位空间；版本号与槽位不一致时 staleness 计算错误，信任域校正失效，这是故障恢复中最隐蔽的失败模式，必须在切换点做版本屏障校验。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统表现</th><th>工程对策</th></tr></thead><tbody><tr><td>带宽不足，槽位写入超 k 步窗口</td><td>双缓冲退化为串行，rollout 停顿</td><td>差量同步 + 基版本校验</td></tr><tr><td>$\\epsilon_s$ 衰减过快</td><td>有效样本比例骤降，吞吐下降</td><td>按任务离线标定 $g(s)$</td></tr><tr><td>版本号与槽位错配</td><td>staleness 误算，校正失效</td><td>切换点版本屏障 + 回滚日志</td></tr></tbody></table>\n<h3 id=\"alg-async-rollout-weight-sync-sec-19\">十九 · 请求形态：只有\"持续不断\"才配得上双缓冲</h3>\n<p>这套负载配方对请求形态的挑剔程度，远高于它对硬件档位的挑剔。异步权重同步的全部收益来自一件事：权重槽切换的那段间隙里，rollout 引擎手上仍有足够多的在飞请求，用当前权重槽继续采样，把等待补全满。因此请求形态必须是持续不断的 rollout 采样流——不是突发式的、不是批末清空的、不是按训练 step 严格对齐的。若 rollout 引擎的请求队列在权重推送到达时恰好接近空，双缓冲切换就退化成一次同步点：切换原子完成，但切换前后没有采样可重叠，等待时间原样保留，收益归零。</p>\n<p>判断请求形态是否合格，看的是队列的\"最低水位\"而非平均水位。设权重推送周期为 $T_{\\text{push}}$（训练侧每 k 步推一次），rollout 引擎在任意时刻的未完成请求数为 $Q(t)$，则重叠收益的下界近似正比于 $\\min_{t \\in [0,T_{\\text{push}}]} Q(t)$。平均值高、但存在周期性低谷的请求流，会在低谷处与权重切换撞车。工程上的做法是把 rollout 请求的生成节奏与训练 step 解耦：训练侧完成一步就立即补充采样任务，而不是等一批样本全部回传后才发起下一批。这与分页 KV 批量 Rollout 所处理的\"批次内请求长短不齐\"是不同层面的问题——那里解决的是单批内部的空洞，这里解决的是批与批之间的空洞。</p>\n<p>代价体现在端到端 RL 吞吐上：请求形态不合格时，rollout 与训练的重叠窗口被压缩，GPU 在权重切换期间重新陷入闲置，异步化的吞吐增益被抵消，而 staleness 带来的信任域调参成本却照付不误——这是最坏的一种组合，付出了 off-policy 校正的复杂度，却没换到重叠收益。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-20\">二十 · 长度分布：长尾决定权重切换的\"在飞半径\"</h3>\n<p>权重槽的回收条件写得很清楚：旧权重槽在无在飞请求后回收。这句话把长度分布直接翻译成了显存占用时长。一个用旧权重生成、长度落在分布长尾的请求，会让旧权重槽在整个生成长度内无法释放，双缓冲实际退化为\"三份权重常驻\"——当前槽、备用槽、待回收槽。长度分布的 P99 与 P50 之比越大，这个在飞半径越长，权重显存的峰值占用越高。</p>\n<p>设请求长度分布为 $L$，旧权重槽的期望占用时长为 $\\mathbb{E}[L \\mid \\text{staleness} &gt; 0]$，即所有跨越权重切换点的请求的剩余生成长度均值。这个量不是全局平均长度，而是被切换点\"截断\"后的条件期望：切换点越靠近请求起始，剩余长度越长。因此把权重推送安排在请求平均完成度较高的时刻，能显著缩短旧槽占用。一个可操作的伪代码思路是：</p>\n<div class=\"formula\">$$\\text{push\\_ok} \\Leftarrow \\Big( \\#\\{\\text{inflight} \\mid \\text{remaining} &gt; L_{0.9}\\} &lt; N_{\\text{th}} \\Big) \\wedge \\big( Q(t) &gt; Q_{\\min} \\big)$$</div>\n<p>即只有当\"剩余长度超过 P90 的在飞请求数\"低于阈值、且队列水位高于下限时才允许推送。这不是拖延推送，而是在长尾与重叠之间取平衡：长尾请求少，旧槽回收快；队列不空，重叠不丢。</p>\n<p>具体例子：一个以短问答为主的 rollout 流，长度分布集中在几百 token 量级，旧槽几乎在切换后立刻可回收，双缓冲的显存代价接近两份权重；而一个混合了长链推理与短工具调用的 Agent rollout 流，长尾请求可能占据单个请求的大部分生成时间，旧槽被单个长请求钉住，显存峰值抬升，此时若权重是全量同步，显存与带宽两头的压力同时上来。代价因此是双重的：显存峰值由长尾决定，而带宽峰值由推送周期决定，两者在长尾场景下同时恶化。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-21\">二十一 · 并发与批大小：调度权在 rollout 引擎，但配方要匹配 staleness 预算</h3>\n<p>批大小由 rollout 引擎调度决定，材料未给出具体数值，这一点必须诚实对待。但配方的逻辑不依赖具体数字：批大小决定了单位时间内产生的样本版本跨度。批越大，单批内跨越权重切换点的样本越多，同一批里 staleness 的方差越大，信任域 $\\epsilon_s = f(\\text{staleness})$ 就越难用一个统一值覆盖。反之批越小，调度开销占比上升，队列水位更容易掉到低谷，重叠收益受损。</p>\n<p>并发数与批大小共同决定 staleness 的分布形状。设一次权重推送后，rollout 引擎在旧权重下继续采样的时长为 $\\tau$，并发请求数为 $C$，则在 $\\tau$ 窗口内产生的旧样本数约为 $C \\cdot \\tau / \\bar{L}$（$\\bar{L}$ 为平均生成长度）。这个数就是训练侧需要按版本号降权或丢弃的样本规模。若它占单批样本的比例过高，有效样本量下降，梯度估计方差上升，训练侧不得不缩小学习率或收紧 $\\epsilon_s$，进一步压低每步的有效更新幅度——staleness 的代价最终以\"每步有效进度\"的形式体现，而不是以墙钟时间体现。</p>\n<p>配方上的判断是：并发与批大小应使\"旧样本占比\"稳定在一个可接受带内，而不是追求最大并发。具体机制上，训练侧按版本号计算 staleness 后对超阈值样本降权或丢弃，这个阈值与并发数是一对耦合参数：并发调高而不动阈值，丢弃率上升；阈值放宽而不动并发，off-policy 比率偏离 1 的程度加深。两者必须一起调，单独调任何一个都会把失败模式从\"样本浪费\"推向\"训练发散\"。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-22\">二十二 · SLO 的错位：端到端 RL 吞吐不等于单请求延迟</h3>\n<p>这套配方的 SLO 以端到端 RL 吞吐与权重切换对在飞请求透明为主，材料未给出具体 SLO 数值。这一点在负载配方里必须讲透：异步权重同步的服务对象是训练进度，不是终端用户的请求延迟。若把在线推理那套 P99 延迟 SLO 套到 rollout 引擎上，会得到完全错误的调度决策——为了压延迟而缩小批、缩短队列，恰好摧毁了重叠所需的请求水位。</p>\n<p>\"对在飞请求透明\"是一条硬约束而非软目标：权重切换不得清空 KV 与块表，不得中断采样请求。它的代价是切换期间新旧权重并存，显存与带宽同时被两份权重占据；它的收益是 rollout 不因同步而出现批次空洞。工程上要监控的不是切换本身的耗时，而是切换前后队列水位的落差——落差大说明透明性只是名义上的，实际发生了请求流失。</p>\n<p>具体例子：一个以端到端 RL 吞吐为 SLO 的部署，权重经 NVLink 或 RDMA 推送到双缓冲槽，推送期间 rollout 继续采样；若运维误把 rollout 引擎的请求超时设得很短，长尾请求在切换窗口内被超时杀掉，队列水位在切换后骤降，下一轮推送又撞上低谷，形成周期性吞吐塌陷。此时表象是\"延迟 SLO 达标\"，实质是重叠收益被超时策略吃掉。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-23\">二十三 · 负载不对时的三种塌陷形态</h3>\n<p>第一种是<b>队列枯竭型</b>：请求流是突发的，批末清空，权重推送落在空队列上。机制上双缓冲切换照常原子完成，但切换间隙无采样可填充，rollout 与训练重新串行。代价是端到端吞吐回落到同步 RL 的水平，而 staleness 校正逻辑仍在运行，等于白付复杂度。识别信号是切换前后队列水位都接近零。</p>\n<p>第二种是<b>长尾钉住型</b>：长度分布长尾过重，旧权重槽被单个长请求长期占用，双缓冲退化为三份权重常驻。代价是显存峰值抬升，若权重为千亿参数全量同步，显存与传输量两头吃紧；若带宽不足，双缓冲切换被传输阻塞，重叠收益被抵消。识别信号是旧槽回收等待时间与请求长度 P99 强相关。</p>\n<p>第三种是<b>版本错配型</b>：并发与批大小把 staleness 分布拉宽，而 $\\epsilon_s$ 仍按固定值收紧，或差量同步的版本号与权重槽不一致，导致样本 staleness 计算错误、信任域校正失效。此时 off-policy 比率 $\\rho_t$ 系统性偏离 1，梯度有偏，阈值不当会直接走向训练发散。这是三种形态里唯一会伤到模型质量的，也是最难从吞吐指标上早期发现的——吞吐看起来正常，甚至因为丢弃率低而偏高，但有效更新已经失真。</p>\n<p>三种形态的共同点是：它们都不是权重同步机制本身的缺陷，而是负载配方与机制不匹配。机制假设\"总有在飞请求可填充、旧槽总能及时回收、版本号总能对齐\"，负载配方的工作就是让这三个假设成立。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-24\">二十四 · 配方的工程落点：把假设变成可观测的门槛</h3>\n<p>把上述三条假设写成可观测的门槛，配方才可执行。队列水位下限 $Q_{\\min}$ 与长尾在飞数阈值 $N_{\\text{th}}$ 构成推送许可条件；旧槽回收等待时间与请求长度 P99 的比值构成显存风险指标；旧样本占比与丢弃率构成 staleness 预算指标。三者联合决定并发、批大小与 $\\epsilon_s$ 的取值，而不是各自独立调参。</p>\n<p>一个具体的工程判断是：当长尾钉住与版本错配同时出现时，优先修版本对齐而不是压长尾。因为版本号与权重槽不一致会让 staleness 计算整体失效，此时无论负载形态多好，信任域校正都是错的；而长尾钉住只损失显存与部分重叠收益，不直接伤模型。修好版本对齐后，再用推送许可条件去削长尾的在飞半径，用并发与批大小的联动去压旧样本占比。这套顺序把\"训练不发散\"放在\"吞吐最大化\"之前，符合异步 RL 流水线里 staleness 是主要风险源的现实。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-25\">二十五 · 负载配方：什么样的采样流才喂得饱双缓冲</h3>\n<p>这套方案的经济性完全建立在“rollout 引擎在权重切换间隙仍有在飞请求可采样”之上，因此负载配方不是可选项而是前提条件。它适合的请求形态是持续不断、彼此独立、无需跨请求状态耦合的 rollout 采样流：长上下文生成、多轮对话中的单轮展开、代码与数学的链式采样都符合，因为单个请求的生命周期足够长，权重槽切换时总有一批请求正处在解码中途，KV 与块表保持不动，切换对它们透明。反过来，短请求、强同步语义的请求形态是它的天敌——若每个请求只有几十个 token 就结束，rollout 引擎会在权重切换前后反复排空批次，双缓冲退化成“切换即空转”，重叠收益归零。</p>\n<p>批大小由 rollout 引擎调度决定，材料未给出具体数值，但配方上的判断是明确的：批要足够大，使一批请求的生成时间显著长于一次权重推送与槽切换的耗时。设单批平均生成时间为 <span class=\"formula\">$$T_{\\text{gen}}$$</span>、一次权重同步耗时为 <span class=\"formula\">$$T_{\\text{sync}}$$</span>，重叠有效的粗略条件是 <span class=\"formula\">$$T_{\\text{gen}} \\gtrsim T_{\\text{sync}}$$</span>；千亿参数模型全量同步传输量大，若 NVLink/RDMA 带宽不足，<span class=\"formula\">$$T_{\\text{sync}}$$</span> 被拉长到超过 <span class=\"formula\">$$T_{\\text{gen}}$$</span>，双缓冲切换就被传输阻塞，rollout 与训练的重叠收益被直接抵消。长度分布同样关键：长度方差过大会让批次尾部拖长，staleness 分布随之变宽，信任域不得不按最旧样本收紧，等于用长尾样本惩罚了整批更新。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>适配判断</th><th>失效表现</th></tr></thead><tbody><tr><td>持续长生成、请求独立</td><td>适配，切换期有在飞请求</td><td>—</td></tr><tr><td>短请求、高并发小批</td><td>不适配</td><td>批次反复排空，重叠收益归零</td></tr><tr><td>长度方差极大</td><td>需截断或分桶</td><td>staleness 分布变宽，信任域过度收紧</td></tr><tr><td>带宽不足的千亿全量同步</td><td>不适配</td><td>切换被传输阻塞，收益抵消</td></tr></tbody></table>\n<p>负载不对时的代价落在三处：吞吐上，rollout 与训练不再真正重叠，端到端 RL 吞吐退回串行水平；稳定性上，staleness 使旧样本的 off-policy 比率偏离 1，阈值不当会导致训练发散，而超参敏感、调参成本高；工程上，差量同步需维护版本与合并逻辑，版本号与权重槽不一致时样本 staleness 计算错误，信任域校正随之失效，故障恢复也更复杂。因此配方应先按长度分桶、限制单批在飞请求数，再让 <span class=\"formula\">$$\\epsilon_s = f(\\text{staleness})$$</span> 随版本号收紧，把负载形状当作与带宽同级的容量约束来规划。</p>\n<h3 id=\"alg-async-rollout-weight-sync-sec-26\">二十六 · 硬件档位：按权重同步路径反推机型</h3>\n<p>部署异步 rollout 权重同步，第一决策不是选框架，而是确定权重从训练引擎到 rollout 引擎走哪条物理路径，因为这条路径决定了双缓冲切换能否真正与采样重叠。Blackwell 平台上有两种档位可选：单节点内 GB200/GB300 NVL72 机柜内，训练与 rollout 进程组共享 NVLink 5 域，权重槽切换可以走 NVLink 的点对点或机柜内全互联带宽；跨节点时则必须走 RDMA（InfiniBand 或 RoCE），权重推送变成网络传输问题。判断标准很直接：把一次权重写入备用槽的时间与一次 rollout 采样批次的最短在飞时长做比较，若写入时间显著短于采样时长，切换对在飞请求就是透明的；若写入时间与采样时长同量级，双缓冲的收益被传输阻塞吃掉，这正是千亿参数全量同步在带宽不足时的失败模式。</p>\n<p>工程上把权重同步的传输代价写成可核算的形式：</p>\n<div class=\"formula\">$$T_{\\text{sync}} = \\frac{B_w \\cdot (1 - c)}{BW_{\\text{link}}} + T_{\\text{merge}}(c),\\quad c \\in [0,1]$$</div>\n<p>其中 $B_w$ 为权重字节数，$c$ 为差量比例，$BW_{\\text{link}}$ 为 NVLink 或 RDMA 的有效带宽，$T_{\\text{merge}}$ 为差量合并与版本校验开销。全量同步时 $c=0$，$T_{\\text{sync}}$ 由带宽线性决定；差量同步时 $c$ 小但 $T_{\\text{merge}}$ 引入版本维护成本。选档位的判据是让 $T_{\\text{sync}}$ 落在采样周期的空闲窗口内：单机柜 NVLink 档位适合全量或高频差量，跨节点 RDMA 档位适合低频差量并配合更长的 $k$ 步间隔。注意这里没有给出具体带宽与模型规模的数值，实际配置时必须用本机实测的 $BW_{\\text{link}}$ 与权重字节数代入上式，而不是照搬他机结论。</p>\n<p>一个具体例子：在 NVL72 机柜内跑一个训练组与两个 rollout 组的解耦部署，训练侧每 $k$ 步把权重差量写入 rollout 组的备用槽，NVLink 域内传输时间远小于一次长序列采样的在飞时长，切换原子完成，rollout 的 KV 与块表保持不动；若把同一模型拆到两个机柜、跨 RDMA 同步，则必须把 $k$ 调大、把差量比例压低，否则 $T_{\\text{sync}}$ 会顶到采样周期上，端到端 RL 吞吐反而低于同步方案。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-27\">二十七 · 并行拓扑：训练组与 rollout 组的切分方式</h3>\n<p>异步权重同步的拓扑不是“训练怎么并行、rollout 就怎么并行”，而是两组各自按自身瓶颈选并行维度，再在权重槽这一层对齐。训练侧通常按张量并行加流水并行切分，因为梯度与优化器状态需要固定切分；rollout 侧则按张量并行加数据并行切分，因为采样是吞吐型负载，需要更多独立请求在飞。两边切分不一致时，权重写入备用槽需要一次重排（reshard），这一步的代价必须计入 $T_{\\text{merge}}$，否则双缓冲切换会被隐式重排拖慢。</p>\n<p>拓扑对齐的伪代码思路如下：</p>\n<ul>\n<li>训练组按 TP=t、PP=p 切分，每步产出带全局版本号 $v$ 的权重分片；</li>\n<li>rollout 组按 TP=r、DP=d 切分，每个 rollout worker 声明自己需要的分片映射；</li>\n<li>权重推送前先做一次分片重排，把训练侧分片映射到 rollout 侧分片，重排结果写入备用槽；</li>\n<li>备用槽写满后原子切换版本号，旧槽标记为待回收，等该槽上的在飞请求计数归零再释放。</li>\n</ul>\n<p>代价落在显存与带宽两处：双缓冲意味着 rollout 侧要常驻两份权重，显存占用翻倍，这对大模型是硬约束，因此 rollout 侧的 TP 度往往要大于训练侧，用更多卡分摊单卡权重常驻量；重排本身是一次全量或差量的数据搬移，若训练与 rollout 的 TP 度不成整数倍关系，重排会产生跨卡通信，进一步抬高 $T_{\\text{merge}}$。工程判断是：优先让 rollout 的 TP 度是训练 TP 度的整数倍，把重排退化为本地切片拼接，避免跨卡重排。</p>\n<p>具体例子：训练侧 TP=8、PP=4，rollout 侧 TP=16、DP=4，则每个 rollout worker 持有的权重分片是训练分片的二分之一，重排只需在同一节点内做切片拼接，NVLink 域内完成；若 rollout 侧 TP=12 而训练侧 TP=8，重排需要跨节点 gather，$T_{\\text{merge}}$ 显著上升，双缓冲切换的原子性也被破坏，此时应改拓扑而不是硬调参数。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-28\">二十八 · 量化方案：权重槽里的数值格式与 staleness 的耦合</h3>\n<p>量化方案在异步权重同步里不是独立的精度选择，而是与 staleness 信任域耦合的变量。权重槽里存的格式决定了 $T_{\\text{sync}}$ 的字节数，也决定了旧样本 logprob 与新策略 logprob 的数值一致性。若训练侧用高精度更新、rollout 侧用 NVFP4 或 FP8 存权重槽，则 $\\rho_t$ 的分子分母来自不同数值格式，比率会带上量化误差，这个误差与 staleness 引起的偏离叠加，信任域收紧的判据就被污染。处理方式是把量化误差纳入 $\\epsilon_s$ 的预算：$\\epsilon_s$ 不仅要覆盖 staleness，还要覆盖权重槽格式与训练格式之间的 logprob 偏差。</p>\n<div class=\"formula\">$$\\epsilon_s = g(\\text{staleness}) + \\delta_{\\text{quant}},\\quad \\delta_{\\text{quant}} = \\left|\\log \\pi_{\\text{slot}}(a_t\\mid s_t) - \\log \\pi_{\\text{train}}(a_t\\mid s_t)\\right|$$</div>\n<p>其中 $\\delta_{\\text{quant}}$ 是同一状态动作在权重槽格式与训练格式下的 logprob 差，$g(\\cdot)$ 是 staleness 的收紧函数。工程含义是：量化越激进，$\\delta_{\\text{quant}}$ 越大，$\\epsilon_s$ 的有效预算被挤占，可用于容忍 staleness 的余量越小，于是必须把 $k$ 步间隔调小或把 staleness 阈值调严。这解释了为什么 NVFP4 量化 rollout 的稳定化必须与权重同步策略一起调，而不是各自独立取最优。</p>\n<p>代价体现在吞吐与显存两侧：低精度权重槽把 $B_w$ 压下来，$T_{\\text{sync}}$ 缩短，双缓冲切换更容易落在采样空闲窗口内，同时 rollout 侧两份权重的常驻显存减半，允许更大的批在飞；但 $\\delta_{\\text{quant}}$ 抬高信任域下限，旧样本被降权或丢弃的比例上升，有效样本吞吐下降。具体例子：千亿参数模型若权重槽用 FP8 存，$B_w$ 相对高精度减半，跨 RDMA 的 $T_{\\text{sync}}$ 相应缩短，但若 $\\delta_{\\text{quant}}$ 已接近 $\\epsilon_s$ 的预算上限，则 staleness 阈值只能取很小，$k$ 步间隔被迫压缩，训练侧更新频率上升又反过来加重同步负担——这是一个必须用实测 logprob 偏差来定标的闭环。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-29\">二十九 · KV 策略：切换期间不清空的前提条件</h3>\n<p>双缓冲权重槽的核心承诺是权重切换对在飞请求透明，而透明的前提是 KV 与块表在切换期间保持。这里要区分两件事：KV 的物理页不因切换而释放，这是分页 KV 管理的基本要求；KV 的语义有效性不因切换而失效，这是本算法要额外保证的。一个在飞请求在旧权重下已经生成了若干 token，其 KV 是旧策略的产物，切换后该请求继续用旧权重槽解码直到结束，新请求才用新权重槽，因此同一批次里可能同时存在两个权重版本的请求。调度器必须按请求粒度记录权重版本号，而不是按批次粒度，否则 staleness 计算会把新请求误标为旧样本。</p>\n<ul>\n<li>块表按请求持有版本标签，切换只改新请求的默认版本，不改在飞请求的标签；</li>\n<li>旧权重槽的回收条件是“该槽版本标签的在飞请求计数为零”，不是“切换完成”；</li>\n<li>KV 页在请求结束前不迁移、不重算，避免切换触发前缀重算导致的延迟尖峰；</li>\n<li>若显存紧张需要抢占，优先抢占新版本请求的等待队列，保留旧版本在飞请求的 KV，防止 staleness 样本被中途丢弃造成版本号断档。</li>\n</ul>\n<p>代价是显存碎片与调度复杂度：两个权重版本并存期间，KV 池要同时服务两套请求，分页分配器的空闲页被两个版本的请求竞争，长序列请求更容易触发抢占；旧槽回收延迟意味着权重常驻显存的时间被在飞请求的最长解码时长拉长，双缓冲的显存翻倍效应在长序列场景下更明显。具体例子：一个长上下文请求在旧权重下解码数千 token，跨越多次权重切换，其 KV 全程保持在旧槽版本标签下，调度器不能因为新版本已切换就把它迁到新槽，否则 $\\rho_t$ 的 $\\theta_{\\text{old}}$ 定义被破坏，信任域校正失去基准。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-30\">三十 · 调度参数：$k$ 步间隔、staleness 阈值与批在飞的联合定标</h3>\n<p>调度参数不是独立旋钮，而是一组互相约束的量：训练侧每 $k$ 步同步一次权重，决定了 staleness 的上界；staleness 阈值决定了多少旧样本被降权或丢弃；批在飞大小决定了权重切换时有多少请求需要保持透明。三者联合定标的思路是先固定可接受的样本丢弃率，再反推 $k$ 与阈值，最后用批在飞大小校验 $T_{\\text{sync}}$ 是否落在空闲窗口内。</p>\n<div class=\"formula\">$$\\text{staleness}_{\\max} \\approx k \\cdot \\frac{T_{\\text{step}}}{T_{\\text{rollout}}},\\quad \\text{drop rate} = \\mathbb{P}\\left(\\text{staleness} &gt; \\text{threshold}\\right)$$</div>\n<p>其中 $T_{\\text{step}}$ 为训练一步的墙钟时间，$T_{\\text{rollout}}$ 为一次 rollout 采样的墙钟时间，比值给出在 $k$ 步同步间隔内 rollout 侧可能累积的版本代数。工程判据是：让 $\\text{staleness}_{\\max}$ 落在信任域还能有效校正的范围内，即 $\\epsilon_s$ 随 staleness 收紧后仍能覆盖多数样本的 $\\rho_t$ 偏离；若 $\\text{staleness}_{\\max}$ 过大，阈值只能取小，丢弃率上升，有效吞吐下降，异步化的收益被抵消。</p>\n<p>代价是超参敏感与调参成本：$k$ 调大则同步开销摊薄、吞吐上升，但 staleness 上界抬高、训练发散风险上升；$k$ 调小则同步频繁、$T_{\\text{sync}}$ 占用采样窗口、重叠收益下降。批在飞大小是第三个约束：批越大，切换时在飞请求越多，旧槽回收越慢，显存翻倍效应越持久；批越小，采样吞吐不足，$T_{\\text{rollout}}$ 变长，同样抬高 staleness 上界。具体例子：在一个训练步与 rollout 采样时长可比的配置里，取 $k$ 使 staleness 上界不超过信任域可校正的代数，同时把批在飞控制在旧槽回收时间不超过一个同步周期的水平；若实测丢弃率超过预设，先降 $k$ 而不是放宽阈值，因为放宽阈值直接削弱 $\\epsilon_s$ 的校正力度，是训练发散的近因。</p>\n<p>最后落在工程判断上：部署配方的可复现性来自把 $T_{\\text{sync}}$、$T_{\\text{merge}}$、$\\delta_{\\text{quant}}$、旧槽回收时间这四个量做成可观测指标，每次调参只动一个旋钮并记录这四个量的变化；版本号与权重槽不一致是这套配方最隐蔽的故障，表现为 staleness 计算错误、信任域校正失效，因此版本号必须与权重槽绑定写入、原子切换，并在样本回传路径上做一致性校验，而不是靠调度器事后推断。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-31\">三十一 · 部署配方的失效边界：staleness 预算、带宽墙与版本一致性</h3>\n<p>这套配方成立的前提是“权重切换开销 &lt; 采样填充窗口”。设单次权重同步耗时为 $T_{\\text{sync}}$（全量传输量 $W$ 除以有效带宽 $B_{\\text{eff}}$，含双缓冲切换与在飞请求排空），采样一轮耗时为 $T_{\\text{roll}}$，则重叠收益的存在条件是 $T_{\\text{sync}} &lt; k\\cdot T_{\\text{roll}}$，其中 $k$ 为两次同步之间的训练步数。一旦千亿参数模型的全量权重经 NVLink/RDMA 推送时带宽不足，$T_{\\text{sync}}$ 超过该窗口，备用权重槽迟迟无法就绪，双缓冲退化为单缓冲，rollout 被迫在切换点等待，异步化的吞吐收益被抵消，端到端表现回落到同步 RL 的水平——这是配方最先失效的地方，也是选型时必须先测的量。</p>\n<p>staleness 预算决定了信任域超参的可调空间。样本按版本号计算 $s=v_{\\text{train}}-v_{\\text{sample}}$，$\\epsilon_s$ 随 $s$ 单调收紧，超过阈值的样本降权或丢弃。代价是双重的：阈值偏松，off-policy 比率 $\\rho_t$ 偏离 1，梯度有偏直至发散；阈值偏紧，大量样本被丢弃，等效批大小缩水，GPU 采样算力被浪费在不会被采用的轨迹上。工程上应把丢弃率作为一等监控指标，与 $\\epsilon_s$ 曲线联动标定，而不是把 $\\epsilon_s$ 当固定常数写进配置。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统表现</th><th>代价落点</th></tr></thead><tbody><tr><td>有效带宽不足</td><td>双缓冲切换被传输阻塞</td><td>重叠收益归零，吞吐回落</td></tr><tr><td>staleness 阈值失配</td><td>比率偏离 1 或样本大量丢弃</td><td>训练稳定性 / 等效批大小</td></tr><tr><td>版本号与权重槽不一致</td><td>staleness 计算错误，校正失效</td><td>故障恢复复杂度上升</td></tr></tbody></table>\n<p>差量同步把传输量从 $W$ 降到增量 $\\Delta W$，但引入版本与合并逻辑：每个权重槽必须记录其对应的训练步号，样本回传的版本号必须能映射到槽内容，否则 staleness 计算整体失真。故障恢复时若槽状态与版本号不同步，重启后无法判断在飞请求属于哪个策略，只能保守丢弃。因此配方应默认“全量同步 + 双缓冲”作为基线，仅在带宽实测充裕且版本管理链路可验证时启用差量；KV 与块表在切换期间保持不清空，是这套配方唯一不付额外代价的部分，应作为硬约束写进调度器。</p>\n<h3 id=\"alg-async-rollout-weight-sync-sec-32\">三十二 · 双缓冲切换的带宽账：全量与差量两条路</h3>\n<p>权重同步在系统层面的第一笔开销是搬运本身。双缓冲权重槽的设计把“切换”做成一次原子指针翻转，但翻转之前必须把新权重完整落到备用槽里；翻转是瞬时的，搬运不是。于是端到端重叠收益的上限由一条简单的不等式决定：设单次权重体积为 <span class=\"formula-inline\">$W$</span>（字节），可用推送带宽为 <span class=\"formula-inline\">$B$</span>，训练侧两次同步之间的间隔为 <span class=\"formula-inline\">$T_{\\text{step}}\\cdot k$</span>，则搬运占空比为</p>\n<div class=\"formula\">$$\\eta_{\\text{sync}}=\\frac{W/B}{k\\,T_{\\text{step}}},\\qquad \\eta_{\\text{sync}}&lt;1\\ \\text{才不阻塞双缓冲切换}$$</div>\n<p>只要 <span class=\"formula-inline\">$\\eta_{\\text{sync}}$</span> 逼近 1，备用槽还没填满，训练侧已经要发起下一次同步，rollout 引擎被迫在“用更旧的权重继续采样”和“停下来等搬运”之间选一个——这正是重叠收益被抵消的临界点。全量同步在千亿参数模型上 <span class=\"formula-inline\">$W$</span> 极大，走 NVLink 域内推送尚可，跨节点就必须落到 RDMA；差量同步把 <span class=\"formula-inline\">$W$</span> 压到稀疏更新的量级，但代价从带宽转移到元数据：需要维护版本号、差量链的合并顺序，以及“某次差量丢失后如何从最近一个全量锚点重建”的恢复逻辑。工程判断很直接：节点内 NVLink 拓扑优先全量、跨 RDMA 域优先差量加周期性全量锚点，锚点间隔由故障恢复时间目标反推，而不是由带宽单独决定。</p>\n<p>具体例子：一个训练侧每 k 步推送一次全量权重的流水线，若 <span class=\"formula-inline\">$W/B$</span> 接近 <span class=\"formula-inline\">$k\\,T_{\\text{step}}$</span>，则每次切换都恰好卡在下一轮同步的门槛上，rollout 的在飞请求虽不被清空，但新请求拿到的权重版本会系统性滞后一到两个版本，staleness 分布从“集中在 1”扩散成“长尾”。这不是调参能救的，是带宽预算问题。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-33\">三十三 · 显存的三份占用：权重槽、KV、在飞样本</h3>\n<p>双缓冲意味着 rollout 引擎侧同时驻留两份权重（当前槽与备用槽），这是显存账的第一项。第二项是 KV cache 与块表——机制要求权重切换期间 KV 与块表保持，不清空批次，因此 KV 的驻留量不随同步节奏起伏，反而因为“采样请求不中断”而长期维持在高水位。第三项是在飞样本：已生成但尚未回传训练侧的样本要携带权重版本号，其 logprob、token 序列与元数据在回传前占住缓冲。</p>\n<p>把三项写成约束：设单卡显存为 <span class=\"formula-inline\">$M$</span>，两份权重占 <span class=\"formula-inline\">$2W_{\\text{dev}}$</span>，KV 池占 <span class=\"formula-inline\">$M_{\\text{kv}}$</span>，在飞缓冲占 <span class=\"formula-inline\">$M_{\\text{fly}}$</span>，则可用于激活与临时 workspace 的余量为</p>\n<div class=\"formula\">$$M_{\\text{work}}=M-2W_{\\text{dev}}-M_{\\text{kv}}-M_{\\text{fly}}$$</div>\n<p>规模上去以后最先崩的往往不是算力而是这个余量：<span class=\"formula-inline\">$M_{\\text{kv}}$</span> 随并发与上下文长度线性涨，<span class=\"formula-inline\">$M_{\\text{fly}}$</span> 随 staleness 容忍窗口涨（窗口越宽，允许滞留的旧版本样本越多），而 <span class=\"formula-inline\">$2W_{\\text{dev}}$</span> 是刚性的。于是“放宽 staleness 阈值换吞吐”这个动作会同时吃掉显存：阈值放宽 → 在飞窗口变大 → <span class=\"formula-inline\">$M_{\\text{fly}}$</span> 上升 → <span class=\"formula-inline\">$M_{\\text{work}}$</span> 下降 → 批大小被迫收缩 → 吞吐回吐。这是一个负反馈环，调参时必须把它当成耦合约束而不是两个独立旋钮。</p>\n<p>具体例子：把 staleness 阈值从“仅容忍一个版本”放宽到“容忍三个版本”，在飞样本的版本分布从单峰变成三峰，回传侧的排序与降权逻辑要按版本分桶处理，缓冲占用近似三倍；若 KV 池已在高水位，这一放宽会直接把可用 workspace 压到无法维持原批大小的程度。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-34\">三十四 · 通信拓扑：版本号也是一条消息</h3>\n<p>容易被忽略的是，权重同步不只是大块数据传输，还是一条控制流：训练侧要告知 rollout 侧“新版本 v+1 已就绪”，rollout 侧要在切换后回执“旧槽已无在飞请求、可回收”，样本回传时要带上生成时的版本号。这些消息量小但要求有序，且必须与数据面的大块传输解耦，否则一次大块传输的拥塞会拖住版本切换的信令，让 rollout 侧误以为新权重可用而实际槽未填满。</p>\n<p>设计上应把权重推送做成“数据面 + 完成栅栏”两段：数据面走 NVLink 或 RDMA 的大块通道，完成栅栏走独立的低延迟通道，栅栏到达才允许原子翻转。伪代码思路是</p>\n<div class=\"formula\">$$\\text{push}(W_{v+1}\\to \\text{slot}_B);\\ \\text{fence}();\\ \\text{atomic.swap}(\\text{slot}_A,\\text{slot}_B);\\ \\text{notify}(v+1)$$</div>\n<p>代价体现在尾延迟上：栅栏与通知的往返若与数据面共享队列，切换的可见延迟会被最大块传输的尾部支配，形成“平均很快、P99 很慢”的形态。规模上去后，跨节点 RDMA 的完成语义与节点内 NVLink 不同，混合拓扑下必须按最慢链路设定栅栏超时，否则会出现部分 rollout 副本已切新权重、部分仍在旧权重的分裂窗口——此时同一批样本的 staleness 计算基准不一致，信任域校正失去统一参照。</p>\n<p>具体例子：NVL72 域内权重推送走 NVLink，域间走 RDMA；若翻转信令统一走域间通道，则域内副本的切换被域间往返拖慢，形成跨域偏斜。正确做法是按域分层栅栏，域内先切、域间后切，并让样本版本号携带域标识，使 staleness 计算能识别这种结构性滞后而非误判为随机滞后。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-35\">三十五 · 功耗与热：重叠不等于免费</h3>\n<p>异步化的收益叙事是“rollout 与训练重叠，等待时间被采样填充”，但重叠意味着训练侧与 rollout 侧同时满载。同步模式下，权重广播期间训练侧算力空闲、rollout 侧等待，整机功耗有一个自然的低谷；异步模式下这个低谷消失，整机长时间贴近功耗上限运行。对 GB200/GB300 NVL72 这类机柜级系统，功耗上限是机柜级约束而非单卡约束，持续贴近上限会触发降频策略，而降频对两类负载的影响不对称：训练侧的大矩阵乘对频率相对不敏感（受限于内存带宽与通信），rollout 侧的解码阶段却是延迟敏感的，频率下滑直接抬高出 token 间隔。</p>\n<p>于是出现一个反直觉的工程判断：异步流水线的吞吐上限有时不是被 staleness 或带宽卡住，而是被机柜功耗预算卡住——把重叠度推到 100% 会让两侧同时争抢功耗额度，降频后的净吞吐可能低于留出 10% 空闲窗口的方案。功耗预算应作为调度器的显式约束：在权重推送窗口内允许训练侧降载，把额度让给 rollout 的解码关键路径，因为推送窗口本身就是训练侧天然的等待期，用它做功耗调度不额外损失训练吞吐。</p>\n<p>具体例子：一次全量权重推送持续的时间窗口内，训练侧无有效计算，若此时仍维持满频满压，功耗被无谓占用；把该窗口标记为“低载窗口”并允许 rollout 侧提频，可在不增加机柜总功耗的前提下压缩解码尾延迟。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-36\">三十六 · 尾延迟：staleness 分布的长尾才是真问题</h3>\n<p>平均 staleness 是个误导性指标。真正决定训练稳定性的是 staleness 分布的尾部：少数滞留很久的样本带着极旧的权重版本回传，其 off-policy 比率 <span class=\"formula-inline\">$\\rho_t$</span> 偏离 1 的程度远超信任域能校正的范围，被降权或丢弃；丢弃率上升又反过来降低有效样本吞吐，形成“看起来吞吐很高、有效样本很少”的假象。尾部的成因通常是结构性的：某个 rollout 副本因权重槽回收等待而滞后、某条跨域链路的栅栏超时、某个长序列请求跨越了多次权重切换。</p>\n<p>把有效吞吐写成丢弃率的函数：设名义样本率为 <span class=\"formula-inline\">$R$</span>，staleness 超阈丢弃比例为 <span class=\"formula-inline\">$d$</span>，则有效样本率为 <span class=\"formula-inline\">$R(1-d)$</span>；而 <span class=\"formula-inline\">$d$</span> 随阈值收紧而上升、随阈值放宽而下降但单样本权重质量下降。两者不是单调可调的：放宽阈值降低 <span class=\"formula-inline\">$d$</span> 却让 <span class=\"formula-inline\">$\\epsilon_s$</span> 覆盖更宽的比率区间，梯度方差上升。工程上应监控的是 staleness 的 P99 与丢弃率的联合曲线，而不是单独盯吞吐。</p>\n<p>具体例子：长序列 rollout 请求跨越两次权重切换后回传，其版本号落后两代，若阈值只容忍一代则被整条丢弃——一条长样本的生成成本远高于短样本，这种丢弃对有效吞吐的伤害被样本长度放大。缓解手段是按请求长度分级设定 staleness 阈值，让长请求获得更宽的版本窗口，代价是这批样本的 <span class=\"formula-inline\">$\\epsilon_s$</span> 更紧，用信任域换取不被浪费的生成算力。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-37\">三十七 · 规模上去以后哪里先崩：一条排序</h3>\n<p>把上述代价按规模敏感性排序，可以得到一条可操作的崩溃顺序。第一崩的是显存余量 <span class=\"formula-inline\">$M_{\\text{work}}$</span>：<span class=\"formula-inline\">$2W_{\\text{dev}}$</span> 刚性、<span class=\"formula-inline\">$M_{\\text{kv}}$</span> 与 <span class=\"formula-inline\">$M_{\\text{fly}}$</span> 随并发与 staleness 窗口涨，余量最先被挤穿，表现为批大小被迫收缩。第二崩的是跨域带宽占空比 <span class=\"formula-inline\">$\\eta_{\\text{sync}}$</span>：模型变大使 <span class=\"formula-inline\">$W$</span> 涨，而 <span class=\"formula-inline\">$k\\,T_{\\text{step}}$</span> 受训练侧步时约束不能无限拉长，占空比逼近 1 后双缓冲切换被传输阻塞。第三崩的是尾延迟与丢弃率的耦合：前两项压力会迫使调度器放宽 staleness 阈值，阈值放宽使尾部变长、丢弃率与梯度方差同时上升。功耗与降频通常在这三者之后才显现，因为它是前两者导致满载重叠的直接后果。</p>\n<p>对应的工程动作也应按这个顺序排优先级：先做权重槽的显存预算硬隔离（把 <span class=\"formula-inline\">$2W_{\\text{dev}}$</span> 与 KV 池分开核算，不允许互相借用），再做分层栅栏与差量加锚点的带宽方案，最后才动 staleness 阈值——把阈值当作最后的手段而非首选旋钮，因为它是唯一同时影响显存、有效吞吐与训练稳定性的耦合参数。规模继续上行时，真正先失效的往往不是某个单点机制，而是“阈值可调”这个假设本身：当 staleness 分布因拓扑分层而多峰化，单一 <span class=\"formula-inline\">$\\epsilon_s=f(\\text{staleness})$</span> 已无法同时覆盖域内与域间样本，此时需要按版本与域联合分桶的信任域，而不是继续调一个标量。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-38\">三十八 · 当权重推送本身成为瓶颈：带宽、显存与尾延迟的连锁失效</h3>\n<p>异步流水线把串行等待转成了重叠执行，但重叠收益的上限由权重推送的带宽占用决定。设单次推送量为 <span class=\"inline-math\">$B_w$</span>（全量同步时即整个参数张量，差量同步时为增量块），推送耗时 <span class=\"inline-math\">$T_{\\text{push}}=B_w/\\text{BW}_{\\text{eff}}$</span>，其中 <span class=\"inline-math\">$\\text{BW}_{\\text{eff}}$</span> 是 NVLink 或 RDMA 在与其他集合通信争用后的有效带宽。只有当 <span class=\"inline-math\">$T_{\\text{push}}$</span> 小于训练侧 k 步的计算时间，双缓冲切换才真正被采样填满；一旦推送占满链路，rollout 侧的在飞请求虽不清空 KV 与块表，但新权重槽迟迟无法原子切换，staleness 单调累积，信任域被迫持续收紧，样本被降权或丢弃的比例上升，端到端吞吐反而回落。千亿参数模型的全量同步正是这条边界最先崩的地方：传输量随参数量线性增长，而链路带宽是固定的。</p>\n<p>显存侧的代价不在权重本身，而在双缓冲的副本与版本簿记。rollout 引擎需常驻两份权重槽，叠加 KV cache 与块表，单卡可用显存被压缩，批大小上限随之下降；差量同步虽省带宽，却要求两侧维护版本号与增量合并逻辑，合并缓冲又是一份额外占用。更隐蔽的是尾延迟：权重切换瞬间，新请求走新槽、在飞请求走旧槽，两套权重同时驻留，若旧槽回收被长序列在飞请求拖住，显存峰值出现在切换窗口而非稳态，容量规划必须按峰值而非均值留余量。</p>\n<table class=\"mini\"><thead><tr><th>规模上升时</th><th>先崩的环节</th><th>系统表现</th></tr></thead><tbody><tr><td>参数量增大</td><td>权重推送带宽</td><td>切换被传输阻塞，重叠收益抵消</td></tr><tr><td>并发请求增多</td><td>双缓冲显存</td><td>批大小下降，KV 与权重槽争显存</td></tr><tr><td>版本迭代加快</td><td>staleness 与信任域</td><td>样本丢弃率上升，比率偏离 1</td></tr></tbody></table>\n<p>功耗与故障恢复是两条常被忽略的边界。训练与 rollout 两个进程组同时满载，整机功耗抬升，若供电或散热按串行工况设计，异步化后会在持续双高负载下触发降频，有效带宽与算力同时缩水。故障恢复则更棘手：版本号与权重槽不一致时，样本携带的 staleness 计算错误，信任域校正失效，训练侧会以错误的 <span class=\"inline-math\">$\\epsilon_s$</span> 约束比率，这种错误不报错、只表现为梯度有偏。工程判断是：把推送带宽预算与 staleness 阈值一起纳入容量规划，先测 <span class=\"inline-math\">$T_{\\text{push}}$</span> 与 k 步计算时间的比值，再决定全量还是差量同步——比值接近 1 时，异步化的收益已经所剩无几。</p>\n<h3 id=\"alg-async-rollout-weight-sync-sec-39\">三十九 · 精度漂移：staleness 与比率的可观测偏差</h3>\n<p>异步流水线最先出问题的不是显存，而是比率。样本回传时携带生成权重版本号，训练侧按版本号算出 staleness，再据此收紧信任域。失效路径很具体：版本号与权重槽不一致，staleness 被算小，$\\epsilon_s$ 放得过宽，旧样本的 off-policy 比率 $\\rho_t$ 偏离 1 却未被裁剪，梯度被这些样本主导。监控上不能只看 loss，要盯三个量：批次内 $\\rho_t$ 的分位数（尤其 99 分位）、按版本号分桶的样本占比、以及被丢弃/降权样本的比例。当 99 分位 $\\rho_t$ 持续越出 $1\\pm\\epsilon_s$ 而丢弃率不升，说明版本号链路断了——样本标的是新版本，实际由旧槽生成。诊断手段是把版本号当作一等公民：每个采样请求在入队时打上槽 ID，出队时校验槽 ID 与当前活跃槽一致，不一致即标记可疑并单独计数。这条校验的代价是每请求一次比较，可忽略；换来的是把“静默偏差”变成“可计数事件”。</p>\n<div class=\"formula\">$$\\rho_t=\\frac{\\pi_{\\theta_{\\mathrm{new}}}(a_t\\mid s_t)}{\\pi_{\\theta_{\\mathrm{old}}}(a_t\\mid s_t)},\\quad w_t=\\min\\big(\\rho_t,\\ \\mathrm{clip}(\\rho_t,1-\\epsilon_s,1+\\epsilon_s)\\big)$$</div>\n<p>工程判断：比率监控要按 staleness 分桶画分布，而不是全局平均。全局均值会把“大量新鲜样本 + 少量极旧样本”的混合掩盖成健康曲线。具体例子：某批次 95% 样本 staleness 为 1 步、5% 为 8 步，全局 $\\rho_t$ 均值接近 1，但 8 步桶的 99 分位已远超阈值，训练在该桶上发散；分桶监控能在发散前把阈值收紧或直接丢弃该桶。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-40\">四十 · 权重槽切换的 OOM 与传输阻塞</h3>\n<p>双缓冲权重槽的显存账要单独算。rollout 引擎同时持有两个槽，加上 KV 与块表，峰值显存是“两份额外权重 + 在飞 KV”。千亿参数模型全量同步时，备用槽写入期间主槽仍在采样，两块权重常驻，这是 OOM 的第一来源；第二来源是切换瞬间旧槽回收滞后——在飞请求未清空，旧槽不能释放，新请求又已指向新槽，瞬时三份权重视图（主、备、待回收）叠加。诊断信号是切换窗口内的显存曲线出现台阶且不回落，配合“旧槽在飞请求计数”长期不归零。回收策略要按在飞请求计数而非固定延时：计数归零即释放，计数长期不降则说明有请求卡在长序列生成上，需要单独的超时驱逐。</p>\n<p>传输阻塞是另一类：全量同步在 NVLink/RDMA 上传输量大，若带宽被采样侧 KV 传输挤占，备用槽写入变慢，切换被推迟，rollout 与训练的重叠收益被抵消。可观测指标是“槽写入完成到切换的时间差”与“切换被推迟的累计时长”。判断准则：当推迟时长占训练 step 时长的比例上升，说明同步已从后台任务变成关键路径，此时应改差量同步或降低同步频率。差量同步的代价是版本与合并逻辑：合并顺序错、版本跳号都会让槽内容与版本号脱节，正是第一节精度问题的根因，因此差量路径必须带合并校验和（对合并后槽做轻量哈希比对）。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-41\">四十一 · 批抖动与路由不均</h3>\n<p>权重切换对在飞请求透明，但新请求的分布会突变：切换后新请求用新权重，若新旧策略在同一 prompt 分布上行为差异大，生成长度分布随之跳变，批内序列长度方差上升，连续批处理的填充与调度效率下降，表现为吞吐抖动。监控批抖动看两个量：批内序列长度的变异系数、以及每批实际 token 数与名义容量的比值。比值持续走低说明填充浪费在扩大。诊断上把批次按“切换前后”打标，对比两组的长度分布；若切换后长尾变厚，应在切换窗口内限制新请求入批速率，给调度器一个平滑过渡。</p>\n<p>路由不均出现在多 rollout 引擎实例场景：权重推送按实例逐个进行，先收到新权重的实例策略更新，后收到的仍在旧策略，请求路由若按轮询分发，同一 prompt 会被新旧策略交替处理，样本分布被人为撕裂。可观测信号是各实例的版本号分布直方图——健康时应快速收敛到单一版本，出现双峰即路由不均。修法是把版本号纳入路由键：路由层只把请求发给已确认切换的实例，未切换实例降级为排空模式（不再接新请求，只完成在飞）。代价是切换窗口内可用容量短暂下降，需按实例数预留余量。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-42\">四十二 · 尾延迟尖刺与在飞请求堆积</h3>\n<p>尾延迟尖刺有三个来源，要分开定位。其一，切换窗口内旧槽回收等待在飞请求，长序列请求把回收拖长，新请求排队；其二，权重写入与采样争抢同一条 NVLink/RDMA 链路，采样侧单步延迟抬升；其三，staleness 阈值收紧后大量样本被丢弃，训练侧有效批次变小，回传节奏改变，rollout 侧出现“采样快、回传慢”的背压。区分方法看时间相关性：尖刺与切换时刻对齐是前两类，尖刺与丢弃率上升对齐是第三类。指标上除 P99 延迟，还要看在飞请求数与队列深度的导数——队列深度二阶导为正且持续，说明背压已形成，单纯扩容实例无效。</p>\n<p>处理尾延迟不能靠调大批次，那会放大填充浪费。可行手段是给切换窗口设“在飞请求预算”：窗口内限制新请求入队，让在飞请求优先排空，旧槽回收更快；同时对超过长度阈值的请求做单独通道，避免它们卡住槽回收。代价是窗口内吞吐短时下降，但换来切换的确定性。具体例子：一次切换中 3 个超长序列请求把旧槽回收推迟了数个采样周期，期间新请求全部排队，P99 延迟尖刺；引入长度阈值分流后，长请求走独立通道，槽回收不再被它们阻塞。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-43\">四十三 · 监控面与回滚判据</h3>\n<p>监控面按“版本—槽—样本”三层组织，每层给一个可判定信号。版本层：各实例版本号直方图是否单峰、版本跳号计数。槽层：双槽显存占用、旧槽在飞计数、槽写入到切换的时间差。样本层：按 staleness 分桶的 $\\rho_t$ 分位数、丢弃率、降权比例。三层信号联动才能定位：版本双峰 + 槽写入延迟上升 = 传输阻塞导致的切换滞后；版本单峰 + 样本层 99 分位越界 = 版本号标注错误而非传输问题。回滚判据要预先写死，不能临场判断：当按 staleness 分桶的丢弃率在某桶上连续多个统计窗口超过设定比例，或该桶 $\\rho_t$ 分位数持续越界，即回滚到上一权重版本并暂停差量合并，改用全量同步重建槽内容。回滚动作本身要原子：先把路由切到已确认一致的实例，再重建槽，最后恢复推送，避免回滚过程中再次产生版本错配。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>首要信号</th><th>代价落点</th><th>处置</th></tr></thead><tbody><tr><td>staleness 计算错误</td><td>分桶 $\\rho_t$ 99 分位越界、丢弃率不升</td><td>梯度有偏、训练发散</td><td>校验槽 ID，回滚全量重建</td></tr><tr><td>双槽 OOM</td><td>切换窗口显存台阶不回落</td><td>rollout 容量下降</td><td>按在飞计数回收，长请求分流</td></tr><tr><td>传输阻塞</td><td>槽写入到切换时间差上升</td><td>重叠收益被抵消</td><td>改差量或降同步频率</td></tr><tr><td>路由不均</td><td>实例版本号双峰</td><td>样本分布撕裂</td><td>版本号入路由键，未切换实例排空</td></tr><tr><td>尾延迟尖刺</td><td>队列深度二阶导为正</td><td>P99 延迟、吞吐抖动</td><td>在飞预算 + 长请求独立通道</td></tr></tbody></table>\n<p>回滚的工程判断落在“可重建性”上：差量同步路径必须保留从全量快照重建槽的能力，否则一旦版本与槽内容脱节，回滚只能靠停流重灌，代价是整条流水线清空。因此每次全量同步后打一个快照标记，差量合并只在该标记之后追加；回滚即丢弃标记之后的差量、重放快照。这条机制把故障恢复从“不可控”压到“一次快照重放”，代价是快照占一份额外显存与写入带宽，需与双槽预算一起核算。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-44\">四十四 · 双缓冲权重槽的失效边界：从版本号错位到尾延迟尖刺</h3>\n\n<p>这套方案最脆弱的地方不在采样，而在版本号与权重槽的一致性。样本回传时携带的是生成时的权重版本号，训练侧据此计算 staleness 并收紧信任域；一旦版本号与槽内实际权重错位，staleness 被低估，旧样本就以接近 1 的 off-policy 比率进入梯度，信任域校正形同虚设。差量同步正是错位的高发区：差量需要按序合并到备用槽，若某次推送因 RDMA 拥塞或进程重启而丢失、重放或乱序，槽内权重就成了若干版本拼接的混合体，而版本号仍单调递增。诊断手段是给每个槽维护权重哈希并与版本号绑定，训练侧在合并后校验哈希，不匹配即拒绝该槽切换并回退到上一稳定版本；同时把回传样本的版本号分布做成直方图，正常应集中在最近 k 个版本，若长尾突然变厚，说明切换被阻塞或样本在飞时间过长。</p>\n\n<p>千亿参数模型上全量同步的传输量是硬约束。权重经 NVLink 或 RDMA 推送，双缓冲切换本应原子完成，但若带宽被采样侧的在飞请求挤占，切换就被传输阻塞，rollout 与训练的重叠收益被抵消——表现为批抖动：采样批次时大时小，GPU 利用率在切换窗口出现凹陷。系统代价可直接写成重叠收益的判据：设单次全量同步耗时为 $T_{\\text{sync}}$、训练步长为 $T_{\\text{step}}$、rollout 单批采样耗时为 $T_{\\text{batch}}$，则有效重叠要求 $T_{\\text{sync}} &lt; T_{\\text{step}}$，否则训练侧在等槽、rollout 侧在等权重，两端同时空转。工程上应监控槽切换的排队深度与切换耗时占训练步长的比例，比例逼近 1 时改用差量同步或降低同步频率 k，代价是 staleness 上限抬高、$\\epsilon_s$ 必须更紧。</p>\n\n<p>路由不均与尾延迟尖刺往往同源。rollout 引擎按请求调度批大小，权重切换后新请求走新槽、旧槽等无在飞请求才回收；若某些长序列请求在旧槽上迟迟不结束，旧槽回收被拖住，新槽的显存与块表压力上升，调度器把更多请求压到少数副本上，形成路由不均，尾延迟尖刺随之出现。监控应盯三个量：旧槽在飞请求数的最长驻留时间、各 rollout 副本的批大小方差、以及 P99 采样延迟相对 P50 的倍数。回滚策略要分层：单槽哈希校验失败只回退该槽；切换耗时连续超阈值则临时冻结切换、让 rollout 在旧权重上多跑若干批并同步收紧 $\\epsilon_s$；若 staleness 直方图长尾持续变厚且梯度范数异常抬升，直接回滚到上一稳定权重版本并丢弃超阈值样本，宁可损失一轮重叠也不让发散样本进入更新。</p>\n\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>版本号与槽错位</td><td>槽哈希不匹配、staleness 直方图长尾变厚</td><td>信任域失效、梯度有偏</td><td>拒绝切换、回退稳定版本</td></tr><tr><td>同步阻塞切换</td><td>切换耗时/训练步长逼近 1、批大小凹陷</td><td>重叠收益归零、GPU 空转</td><td>降 k 或改差量同步</td></tr><tr><td>旧槽回收拖延</td><td>在飞驻留时间长、副本批大小方差大</td><td>显存压力、尾延迟尖刺</td><td>冻结切换、限流长序列</td></tr></tbody></table>\n<h3 id=\"alg-async-rollout-weight-sync-sec-45\">四十五 · 选型的第一性问题：等待从哪来、偏差从哪来</h3>\n<p>把异步 rollout 权重同步放进同族算法里比较，先要问的不是“哪个更快”，而是“被消除的等待属于哪一类、被引入的偏差由谁吸收”。同步 RL 的等待来自训练 step 与权重广播的串行：rollout 引擎在权重未到之前无事可做，GPU 空转。异步化把这段等待用采样填满，代价是把 on-policy 变成 off-policy。因此选型的第一性判据是两条正交轴：<strong>权重更新的传输成本</strong>（全量还是差量、走 NVLink 还是 RDMA、模型是否千亿级）与<strong>staleness 的可容忍度</strong>（任务对策略偏移的敏感度、信任域超参是否可调）。批不变内核、NVFP4 量化稳定化这些邻居解决的是数值可复现与量化误差，它们不改变调度结构；本算法改变的是调度结构本身，所以它不能与它们互换，只能叠加。</p>\n<p>决策时先做一个粗判：若单步训练时间远大于权重广播时间，串行等待占比小，异步化的收益上限就低，此时应优先做批不变与量化稳定，而不是引入 staleness。反之，若广播在千亿参数上成为瓶颈、rollout 队列长期饥饿，异步化才是主矛盾。这个判断不需要精确数字，只需要比较两个量级：训练 step 时长与权重传输时长。</p>\n<div class=\"formula\">$$\\text{收益上限}\\approx\\frac{T_{\\text{bcast}}}{T_{\\text{step}}+T_{\\text{bcast}}},\\qquad \\text{偏差代价}\\propto \\mathbb{E}\\left[\\left|\\rho_t-1\\right|\\right]$$</div>\n<p>前者决定值不值得做，后者决定做得多激进。工程上常见的错误是先上异步再调信任域，结果超参搜索的成本超过吞吐收益；正确顺序是先确认传输占比，再决定是否用差量同步压缩 $T_{\\text{bcast}}$。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-46\">四十六 · 同族算法的分工边界</h3>\n<p>同族里每个算法都在回答“rollout 与训练如何共存”，但切入点不同，混用会互相抵消。分页 KV 批量 Rollout 管的是显存碎片与批内 KV 复用，它决定 rollout 引擎能同时挂多少在飞请求；分块预填背驮解码与分块预填搭载解码管的是预填与解码的时间重叠，决定单请求的尾延迟；预填解码分离 Rollout 与 KV 中心分离式池化管的是资源池化与跨实例 KV 搬运；特征级投机采样 Rollout 管的是每 token 的算力节省；批不变 Rollout 采样管的是 logprob 可复现，是信任域比率可信的前提；NVFP4 量化 Rollout 稳定化管的是低精度下的数值漂移；在线 Rollout 剪枝管的是样本预算；异构 Agent 协同 Rollout 管的是多角色流水；Rollout 前缀 KV 共享管的是公共前缀的重复计算。</p>\n<p>本算法的独特位置在于它是唯一直接改动“权重版本”这一维度的：其他算法都在同一权重版本内优化吞吐或数值，只有它让不同样本携带不同版本号。因此它与批不变采样的关系是依赖而非替代——若 logprob 在同版本内都不可复现，$\\rho_t$ 的分母就不可信，staleness 校正失去基准。它与 NVFP4 量化稳定化的关系是叠加：量化误差会放大 $\\rho_t$ 的方差，在 staleness 已经收紧 $\\epsilon_s$ 的情况下，量化噪声可能吃掉信任域留下的余量，因此低精度部署时应把 $\\epsilon_s$ 的收紧曲线与量化误差上界一起标定。</p>\n<table class=\"mini\"><thead><tr><th>相邻算法</th><th>它改变的维度</th><th>与本算法的关系</th><th>选型含义</th></tr></thead><tbody><tr><td>批不变 Rollout 采样</td><td>同版本内 logprob 可复现</td><td>前置依赖</td><td>缺失时 staleness 校正不可信，应先补</td></tr><tr><td>NVFP4 量化 Rollout 稳定化</td><td>数值精度与漂移</td><td>叠加，共享信任域预算</td><td>低精度下 $\\epsilon_s$ 需与量化误差联合标定</td></tr><tr><td>分页 KV 批量 Rollout</td><td>显存与在飞批容量</td><td>承载层</td><td>决定双缓冲切换时能保住多少在飞请求</td></tr><tr><td>预填解码分离 Rollout</td><td>资源池化与拓扑</td><td>可组合</td><td>分离后权重推送路径变长，传输成本上升</td></tr><tr><td>特征级投机采样 Rollout</td><td>每 token 算力</td><td>正交</td><td>投机接受率随 staleness 下降，需重估草稿模型</td></tr><tr><td>在线 Rollout 剪枝</td><td>样本预算</td><td>正交但交互</td><td>剪枝阈值应按版本号分层，避免旧版本样本被误留</td></tr></tbody></table>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-47\">四十七 · 决策表：按约束选主算法</h3>\n<p>把选型写成可执行的判定，而不是罗列优缺点。下面按工程约束给出主算法选择，判据是“当前最贵的代价项是什么”。若最贵的是权重广播阻塞，选本算法并配差量同步；若最贵的是 KV 显存，选分页 KV 批量；若最贵的是尾延迟，选分块预填搭载解码；若最贵的是数值不可复现导致训练不稳，选批不变采样。注意这些选择不是互斥的，主算法决定调度骨架，其余作为插件叠加。</p>\n<table class=\"mini\"><thead><tr><th>约束信号</th><th>主算法</th><th>关键配套</th><th>不适用条件</th></tr></thead><tbody><tr><td>rollout 队列饥饿、广播占 step 时长显著</td><td>异步 rollout 权重同步</td><td>差量同步 + 版本号回传</td><td>模型小、广播可忽略；任务对策略偏移极敏感</td></tr><tr><td>KV 显存碎片、在飞批上不去</td><td>分页 KV 批量 Rollout</td><td>块表保持、前缀共享</td><td>序列极短、批已打满</td></tr><tr><td>预填拖尾、解码被预填阻塞</td><td>分块预填搭载解码</td><td>预填解码分离</td><td>预填占比低</td></tr><tr><td>logprob 抖动、比率不可信</td><td>批不变 Rollout 采样</td><td>固定归约顺序</td><td>仅做推理不做 RL</td></tr><tr><td>低精度下策略漂移</td><td>NVFP4 量化 Rollout 稳定化</td><td>误差上界标定</td><td>精度不构成瓶颈</td></tr><tr><td>每 token 算力吃紧</td><td>特征级投机采样 Rollout</td><td>草稿模型随版本更新</td><td>接受率低于阈值</td></tr></tbody></table>\n<p>表里最容易被误判的是第一行与第四行的先后。工程上若发现训练不稳，先怀疑 logprob 不可复现而非 staleness；因为批不变缺失时，即使 staleness 为零，$\\rho_t$ 也会因归约顺序抖动而偏离 1，此时收紧 $\\epsilon_s$ 只是掩盖症状。判定方法是：在同一权重版本内重复采样同一状态，看 logprob 是否逐位一致；不一致则先修批不变，再谈异步。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-48\">四十八 · 适用条件的量化刻画</h3>\n<p>适用条件可以写成三个可测的量：staleness 分布的上分位、信任域收紧后的有效样本率、以及双缓冲切换的阻塞概率。设样本版本号与当前权重版本之差为 $d$，$\\epsilon_s=g(d)$ 单调递减。有效样本率指未被降权或丢弃的样本占比，它随 $g$ 的收紧而下降；若下降过快，吞吐收益被样本浪费抵消。工程上应监控 $\\mathbb{E}[d]$ 与 $\\epsilon_s$ 的乘积：当 staleness 增大而 $\\epsilon_s$ 未同步收紧时，$\\rho_t$ 的尾部会超出裁剪区间，梯度有偏；当 $\\epsilon_s$ 收得过紧，大量样本权重趋零，等于白采样。</p>\n<div class=\"formula\">$$\\text{有效样本率}\\approx\\Pr\\left(\\left|\\rho_t-1\\right|\\le\\epsilon_s(d)\\right),\\qquad \\text{净吞吐}\\approx\\frac{\\text{有效样本数}}{T_{\\text{step}}+T_{\\text{bcast}}^{\\text{residual}}}$$</div>\n<p>具体例子：千亿参数模型全量同步时，若 RDMA 带宽不足以在一步训练时间内完成推送，双缓冲的备用槽迟迟不能切换，rollout 继续用旧槽采样，$d$ 持续累积，$\\epsilon_s$ 被迫收紧到有效样本率骤降，重叠收益被抵消。此时正确动作不是继续调 $\\epsilon_s$，而是改差量同步把 $T_{\\text{bcast}}$ 压到 step 时长以内；差量同步需要维护版本与合并逻辑，故障恢复变复杂，版本号与权重槽不一致会让 staleness 计算错误、信任域校正失效，因此必须把版本号作为样本的一等字段随 KV 与块表一起保持。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-49\">四十九 · 组合与迁移的工程判断</h3>\n<p>组合时的顺序有讲究：先在单版本内把批不变与分页 KV 做稳，让 $\\rho_t$ 的分母可信、在飞批容量足够；再引入双缓冲与版本号，让切换对在飞请求透明；最后才叠加量化与投机。若顺序颠倒，异步引入的 staleness 会与量化噪声、投机接受率下降混在一起，诊断时无法归因。迁移到分离式预填/解码拓扑时，权重推送路径从单机 NVLink 变为跨实例 RDMA，$T_{\\text{bcast}}$ 上升，原本适用的异步方案可能退回不适用；判断标准仍是 $T_{\\text{bcast}}$ 与 $T_{\\text{step}}$ 的比值，而不是拓扑本身。</p>\n<p>另一个判断点是剪枝与异步的交互：在线剪枝按样本价值淘汰，若不分版本，旧版本的高价值样本会被保留而新版本样本被误删，导致训练侧看到的 staleness 分布被人为扭曲。正确做法是按版本号分层剪枝，保证每个版本都有代表样本回传，使 $\\epsilon_s$ 的标定基于真实分布而非幸存者偏差。异构 Agent 协同场景下，多角色各自持有不同版本，版本号需沿角色链路传递，否则跨角色的比率无法对齐。</p>\n<p>最终落在一条可执行的工程规则上：把权重版本号当作与 KV 块表同级的状态来管理，双缓冲槽的切换、样本的回传、剪枝的取舍、信任域的收紧全部以版本号为索引；当版本号与槽不一致时，宁可丢弃该批样本也不要用错误的 staleness 去校正，因为错误的 $\\epsilon_s$ 比不校正更能把梯度推向发散。</p>\n\n<h3 id=\"alg-async-rollout-weight-sync-sec-50\">五十 · 异步权重同步的失效边界：同族调度方案怎么选</h3>\n<p>本方案的适用条件可以压成一句话：只有当 rollout 与训练之间的串行等待时间显著大于权重传输时间时，双缓冲重叠才划算。设单轮同步 RL 的串行时间为 <span class=\"formula\">$$T_{\\text{serial}} = T_{\\text{rollout}} + T_{\\text{train}} + T_{\\text{bcast}}$$</span>，异步化后的稳态周期近似为 <span class=\"formula\">$$T_{\\text{async}} \\approx \\max(T_{\\text{rollout}},\\ T_{\\text{train}}) + \\frac{T_{\\text{bcast}}}{k}$$</span>，其中 k 为每 k 步推送一次权重的间隔。当 <span class=\"formula\">$$T_{\\text{bcast}}$$</span> 接近或超过 <span class=\"formula\">$$T_{\\text{rollout}}$$</span> 时，双缓冲切换被传输阻塞，重叠收益被抵消——千亿参数模型全量同步正是这一失效点，此时要么改差量同步，要么退回同步 RL 并接受 GPU 闲置。工程判断的顺序是：先测权重传输占单轮周期的比例，再决定是否异步化，而不是先上异步再调 staleness 阈值。</p>\n<p>与同族方案对照，差异集中在“谁承担 staleness”这一维度。批不变内核处理的是 logprob 不可复现导致的比率噪声，NVFP4 量化稳定处理的是数值误差放大，两者都不改变样本的生成版本；本方案则主动让样本落后于当前权重，把偏差从数值层搬到调度层，因此必须用 <span class=\"formula\">$$\\rho_t=\\frac{\\pi_{\\theta_{\\mathrm{new}}}(a_t\\mid s_t)}{\\pi_{\\theta_{\\mathrm{old}}}(a_t\\mid s_t)},\\quad w_t=\\min\\big(\\rho_t,\\ \\mathrm{clip}(\\rho_t,1-\\epsilon_s,1+\\epsilon_s)\\big)$$</span> 把旧样本的更新幅度按版本号收紧。选型时若团队无力维护版本号与权重槽的一致性，应优先选批不变内核这类“不引入版本语义”的方案；反之若瓶颈明确在等待权重，才值得引入 staleness 这一新的超参面。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>选异步双缓冲</th><th>选同步或数值类方案</th></tr></thead><tbody><tr><td>权重传输占周期比例</td><td>低，可被采样填充</td><td>高，切换被阻塞</td></tr><tr><td>模型规模与同步方式</td><td>中等规模，差量同步可维护</td><td>千亿全量，带宽不足</td></tr><tr><td>调参预算</td><td>可承担 staleness 阈值扫描</td><td>无力承担发散风险</td></tr><tr><td>故障恢复要求</td><td>可接受版本合并逻辑</td><td>要求简单回滚</td></tr></tbody></table>\n<p>最隐蔽的失效模式是版本号与权重槽不一致：差量同步需要维护版本与合并逻辑，一旦槽切换与版本记录错位，样本 staleness 计算错误，信任域校正随之失效，表现为比率长期偏离 1 而阈值看似正常。这类故障不会立刻发散，却会让训练在错误的方向上缓慢漂移，排查成本远高于同步方案的 GPU 闲置。因此本方案的边界不是“能不能异步”，而是“能不能保证版本语义正确”——做不到这一点，双缓冲带来的吞吐收益不足以抵消诊断代价。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2025 · NVFP4采样与量化稳定性</td></tr><tr><td>解决什么</td><td>同步RL中rollout必须等训练step完成、权重广播后才能开始下一轮，rollout与训练串行导致GPU在等待权重…</td></tr><tr><td>一句话机制</td><td>rollout引擎与训练引擎解耦为两个进程组，训练侧每k步把权重增量（或全量）经NVLink/RDMA推送到rollo…</td></tr><tr><td>代价与失效</td><td>staleness使旧样本的off-policy比率偏离1，信任域需按staleness动态收紧，超参敏感且调参成本高；权重全量同步在千亿…</td></tr><tr><td>后继</td><td>异构Agent协同Rollout</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-async-rollout-weight-sync · 共 8 个片段</p>\n";break;}}})();
